rpg.html:
/* @larch-params {
  "neon": { "type": "color", "label": "霓虹主色", "labelEn": "Neon", "default": "#39f3ff" },
  "pulse": { "type": "color", "label": "第二色", "labelEn": "Second neon", "default": "#ff3fb4" }
} */
/* 霓虹訊號的 RPG：地圖狀態列是一條資料讀數，地名是掛在上面的終端機分頁；暫停選單是滿版 HUD，導覽是底部的工作列；戰鬥是四個角落的 HUD：左上指令終端機、右上隊伍資料、左下遭遇資訊、右下鎖定目標。 */
:root { --surface: #060b16 !important; --ink: #e6fbff !important; --fg: #e6fbff !important; --muted: #a9d6de !important; --line: color-mix(in srgb, var(--skin-neon) 55%, transparent) !important; --control: #0d1a2b !important; --strong: var(--skin-neon) !important; --strong-fg: #060b16 !important; --focus: var(--skin-pulse) !important; --ns-mono: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; --ns-sans: "Noto Sans TC", "PingFang TC", "Microsoft JhengHei", system-ui, sans-serif; --ns-n55: color-mix(in srgb, var(--skin-neon) 55%, transparent); --ns-n35: color-mix(in srgb, var(--skin-neon) 35%, transparent); --ns-n20: color-mix(in srgb, var(--skin-neon) 20%, transparent); --ns-panel: linear-gradient(160deg, rgba(8, 16, 30, .95), rgba(4, 7, 14, .96)); --ns-scan: repeating-linear-gradient(180deg, rgba(255, 255, 255, .025) 0 1px, transparent 1px 3px); --ns-brackets: linear-gradient(var(--skin-neon), var(--skin-neon)) 0 0 / 9px 1.5px no-repeat, linear-gradient(var(--skin-neon), var(--skin-neon)) 0 0 / 1.5px 9px no-repeat, linear-gradient(var(--skin-neon), var(--skin-neon)) 100% 0 / 9px 1.5px no-repeat, linear-gradient(var(--skin-neon), var(--skin-neon)) 100% 0 / 1.5px 9px no-repeat, linear-gradient(var(--skin-neon), var(--skin-neon)) 0 100% / 9px 1.5px no-repeat, linear-gradient(var(--skin-neon), var(--skin-neon)) 0 100% / 1.5px 9px no-repeat, linear-gradient(var(--skin-neon), var(--skin-neon)) 100% 100% / 9px 1.5px no-repeat, linear-gradient(var(--skin-neon), var(--skin-neon)) 100% 100% / 1.5px 9px no-repeat; --ns-cut: linear-gradient(135deg, transparent calc(50% - .8px), var(--skin-neon) calc(50% - .8px) calc(50% + .8px), transparent calc(50% + .8px)); }

/* ── 共用按鈕 ── */
body > :is(header, footer) button, #quest-fold, #loader .loader-actions button, #dialogue :is(.dialogue-actions button, .dlg-choice), .rpg-pause-menu :is(.pm-content button:not(.pm-party-member, .pm-slot-frame, .pm-bag-item), .pm-close), .rpg-battle :is(.bt-talk button, .battle-actions[data-menu="result"] button), .rpg-shop button, .rpg-naming button { border: 0; border-radius: 0; background: rgba(13, 26, 43, .92); color: #e6fbff; box-shadow: inset 0 0 0 1px var(--ns-n55); text-shadow: none; font-family: var(--ns-mono); letter-spacing: .08em; transform: none; }
body > :is(header, footer) button:is(:hover, :focus-visible, [aria-pressed="true"]), #quest-fold:is(:hover, :focus-visible), #loader .loader-actions button:is(:hover, :focus-visible), #dialogue :is(.dialogue-actions button, .dlg-choice):is(:hover, :focus-visible), .rpg-pause-menu :is(.pm-content button:not(.pm-party-member, .pm-slot-frame, .pm-bag-item), .pm-close):is(:hover, :focus-visible, [aria-pressed="true"]):not(:disabled), .rpg-battle :is(.bt-talk button, .battle-actions[data-menu="result"] button):is(:hover, :focus-visible), .rpg-shop button:is(:hover, :focus-visible):not(:disabled), .rpg-shop :is(.shop-tabs button[aria-selected="true"], button.shop-go:not(:disabled)), .rpg-naming button:is(:hover, :focus-visible, .naming-go), #wheel .wheel-cancel:is(:hover, :focus-visible) { background: var(--skin-neon); color: #060b16; text-shadow: none; box-shadow: 0 0 14px color-mix(in srgb, var(--skin-neon) 40%, transparent); }
:where(#loader, #dialogue, .rpg-pause-menu, .rpg-battle, .rpg-shop, .rpg-naming, #wheel, body > header, body > footer, #quest-wrap) :is(button, input):focus-visible { outline: 2px solid var(--skin-pulse); outline-offset: 2px; }
:where(body > header, body > footer, #quest-wrap, .pm-content, .rpg-shop, .rpg-naming) button:not(.pm-slot-frame, .pm-bag-item):active:not(:disabled) { background: var(--skin-pulse); color: #060b16; }
:is(.pm-content, .rpg-shop, .rpg-naming) button:not(.pm-slot-frame, .pm-bag-item):disabled { background: #0b1018; color: #93a3a8; box-shadow: inset 0 0 0 1px #3c4a50; }

/* ── 地圖：狀態列是一條資料讀數，地名是掛在上方的終端機分頁（不裁切，整塊都看得到） ── */
body > header, #quest-wrap #quest, #notice, body > footer .hint, #banner, #dialogue .dlg-box, .bt-talk, .rpg-shop, .rpg-shop .shop-detail, .rpg-naming { border: 0; border-radius: 0; background: var(--ns-panel); color: #e6fbff; box-shadow: inset 0 0 0 1px var(--ns-n55), inset 3px 0 0 var(--skin-neon); backdrop-filter: blur(6px); font-family: var(--ns-sans); }
body > header { top: 30px; left: 16px; margin: 0; gap: 8px; padding: 10px 10px 10px 14px; overflow: visible; clip-path: none; background: var(--ns-scan), var(--ns-panel); }
body > header::before { display: none; }
body > header .location { position: static; display: grid; grid-template-columns: auto auto minmax(0, 1fr); grid-template-areas: "faces hp text"; align-items: center; gap: 4px 10px; min-width: 0; }
body > header .hud-party { display: contents; }
body > header strong#title { position: absolute; left: 10px; top: -23px; bottom: auto; z-index: 1; display: inline-flex; align-items: center; gap: 6px; max-width: calc(100% - 20px); height: 24px; margin: 0; padding: 0 12px; overflow: hidden; border: 0; border-radius: 0; background: #060b16; color: var(--skin-neon) !important; font: 700 13px/24px var(--ns-mono); letter-spacing: .12em; text-overflow: ellipsis; white-space: nowrap; text-shadow: 0 0 8px color-mix(in srgb, var(--skin-neon) 70%, transparent); box-shadow: inset 0 0 0 1px var(--skin-neon), inset 0 -2px 0 #060b16, 0 0 12px color-mix(in srgb, var(--skin-neon) 30%, transparent); clip-path: polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 0 100%); transform: none; }
body > header strong#title::before { flex: none; width: auto; height: auto; margin: 0; border: 0; border-radius: 0; background: none; box-shadow: none; color: var(--skin-pulse); content: "LOC:"; font-size: 10px; letter-spacing: .1em; transform: none; }
body > header #status { color: var(--skin-neon) !important; }
body > header .hud-faces { grid-area: faces; display: flex; gap: 4px; }
body > header .hud-faces::after { display: none; }
body > header .hud-faces canvas { display: block; width: 38px; height: 38px; margin: 0; padding: 3px; border: 0; border-radius: 0; outline: 0; object-fit: cover; background: var(--ns-brackets), #02050b; box-shadow: none; image-rendering: pixelated; }
body > header .hud-faces button.hud-face { padding: 0; border: 0; border-radius: 0; background: none; box-shadow: none; }
body > header .hud-faces button.hud-face canvas { width: 30px; height: 30px; opacity: .8; }
body > header .hud-faces button.hud-face:is(:hover, :focus-visible) { background: none; box-shadow: none; }
body > header .hud-faces button.hud-face:is(:hover, :focus-visible) canvas { opacity: 1; background: var(--ns-brackets), color-mix(in srgb, var(--skin-neon) 20%, #02050b); }
body > header .hud-hp { grid-area: hp; width: 120px; height: 10px; padding: 0; border: 1px solid var(--ns-n55); border-radius: 0; background: #02050b; box-shadow: none; }
body > header .hud-hp i { border-radius: 0; background: repeating-linear-gradient(90deg, transparent 0 6px, #02050b 6px 8px), linear-gradient(90deg, var(--skin-neon), #b8fbff); box-shadow: 0 0 8px var(--ns-n55); }
body > header .hud-hp.low i { background: repeating-linear-gradient(90deg, transparent 0 6px, #02050b 6px 8px), linear-gradient(90deg, var(--skin-pulse), #ffb3dd); }
body > header .hud-hp-text { grid-area: text; display: inline-flex; align-items: center; gap: 8px; color: #a9d6de !important; font: 600 12px/1 var(--ns-mono); white-space: nowrap; }
body > header .hud-hp-text .hud-lv { padding: 2px 6px; border: 0; border-radius: 0; background: var(--skin-pulse); color: #060b16 !important; font: 800 11px/1.2 var(--ns-mono); font-style: normal; }
body > header > button { display: grid; place-items: center; width: 38px; height: 38px; min-height: 38px; padding: 0; font-size: 16px; }
body > header :is(#weapon, #bag) { width: auto; gap: 6px; padding: 0 12px 0 8px; font-size: 12px; }
#quest-wrap #quest { padding: 8px 34px 9px 16px; background: var(--ns-scan), var(--ns-panel); box-shadow: inset 0 0 0 1px var(--ns-n55), inset 3px 0 0 var(--skin-pulse); }
#quest-wrap #quest::before { display: none; }
#quest-wrap #quest small { color: var(--skin-pulse) !important; font-family: var(--ns-mono); letter-spacing: .16em; }
#quest-wrap #quest small::before { border-radius: 0; background: var(--skin-pulse); color: #060b16; }
#quest-wrap #quest span { color: #e6fbff !important; }
#quest-wrap #quest::after { color: var(--skin-neon); }
#quest-wrap #quest:is(:hover, :focus-visible) { box-shadow: inset 0 0 0 1px var(--skin-neon), inset 3px 0 0 var(--skin-pulse), 0 0 16px var(--ns-n35); }
#quest-fold { width: 30px; height: 30px; min-height: 30px; padding: 0; }
.rpg-waypoint { padding: 3px 10px 4px; border: 0; border-radius: 0; background: rgba(6, 11, 22, .92); color: #e6fbff; font: 700 12px/1.35 var(--ns-mono); letter-spacing: .06em; box-shadow: inset 0 0 0 1px var(--ns-n55), inset 2px 0 0 var(--skin-neon); backdrop-filter: none; }
.rpg-waypoint::after, .rpg-waypoint:is([data-kind="exit"], .is-objective, :hover)::after { left: calc(50% - 4px); bottom: -5px; width: 8px; height: 5px; border: 0; background: var(--skin-neon); clip-path: polygon(0 0, 100% 0, 50% 100%); transform: none; }
.rpg-waypoint:is([data-kind="exit"], .is-objective) { background: rgba(6, 11, 22, .92); box-shadow: inset 0 0 0 1px var(--skin-pulse), inset 2px 0 0 var(--skin-pulse); }
.rpg-waypoint:is([data-kind="exit"], .is-objective)::after { background: var(--skin-pulse); }
.rpg-waypoint.is-objective::before { border: 0; border-radius: 0; background: var(--skin-pulse); color: #060b16; }
.rpg-waypoint:hover { background: color-mix(in srgb, var(--skin-neon) 20%, #060b16); color: #fff; }
.rpg-waypoint:focus-visible { outline: 2px solid var(--skin-pulse); outline-offset: 3px; }
#banner { min-width: min(420px, 80vw); padding: 12px 40px 14px; background: var(--ns-scan), var(--ns-panel); clip-path: polygon(14px 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%, 0 14px); }
#banner::before, #banner::after { display: none; }
#banner strong { color: #f2feff; font-family: var(--ns-sans); letter-spacing: .14em; text-shadow: 0 0 2px #fff, 0 0 16px var(--skin-neon); }
#banner small { color: var(--skin-pulse); font-family: var(--ns-mono); letter-spacing: .36em; }
body > footer .pad button { width: 48px; height: 48px; font-size: 20px; }
body > footer #interact { padding: 0 16px; background: var(--skin-neon); color: #060b16; }
body > footer .stick { border: 1px solid var(--ns-n55); border-radius: 50%; background: rgba(6, 11, 22, .7); box-shadow: 0 0 14px var(--ns-n20); }
body > footer .stick i { border: 1px solid var(--skin-neon); background: #060b16; box-shadow: 0 0 10px var(--ns-n55); }
body > footer .stick.active i { background: var(--skin-neon); }
#loader { background: var(--ns-scan), radial-gradient(ellipse 70% 60% at 50% 45%, #0b1c2e, #03050b 75%); color: #e6fbff; }
#loader small { color: var(--skin-pulse); font-family: var(--ns-mono); letter-spacing: .4em; }
#loader strong { color: #f2feff; text-shadow: 0 0 14px var(--skin-neon); }
#loader p { color: #a9d6de; font-family: var(--ns-mono); }
#loader .loader-bar { border: 1px solid var(--ns-n55); border-radius: 0; background: #02050b; }
#loader .loader-bar i { background: repeating-linear-gradient(90deg, transparent 0 8px, #02050b 8px 10px), linear-gradient(90deg, var(--skin-neon), var(--skin-pulse)); }
#loader .loader-motes i { background: var(--skin-neon); box-shadow: 0 0 8px var(--skin-neon); }

@media (max-width: 700px) {
  body > header { top: 30px; left: 12px; gap: 6px; padding: 8px 8px 8px 10px; }
  body > header .location { grid-template-columns: auto minmax(0, 1fr); grid-template-areas: "faces hp" "faces text"; gap: 5px 8px; }
  body > header .hud-faces canvas { width: 34px; height: 34px; }
  body > header .hud-hp { width: 100%; min-width: 96px; }
  body > header .hud-hp-text { gap: 5px; font-size: 11px; }
  body > header > button { width: 34px; height: 34px; min-height: 34px; font-size: 14px; }
  body > header strong#title { font-size: 12px; }
}

/* ── 地圖上的對話 ── */
#dialogue { --dlg-speaker: var(--skin-neon) !important; --dlg-text: #e6fbff !important; --dlg-font: "Noto Sans TC", "PingFang TC", "Microsoft JhengHei", system-ui, sans-serif !important; }
#dialogue .dlg-nameplate { padding: 4px 14px; border: 1px solid var(--skin-neon); border-radius: 0; background: #060b16; box-shadow: 0 0 12px var(--ns-n35); }
#dialogue #speaker { background: none; box-shadow: none; color: var(--skin-neon); font-family: var(--ns-mono); letter-spacing: .14em; }
#dialogue #speaker::before { color: var(--skin-pulse); content: "["; }
#dialogue #speaker::after { color: var(--skin-pulse); content: "]"; }
#dialogue #text { color: #e6fbff; }

/* ── 暫停選單：滿版 HUD，上面一條細細的標題列，導覽是底部的工作列 ── */
.rpg-pause-menu { --pm-bg: #060b16; --pm-fg: #e6fbff; --pm-muted: #a9d6de; --pm-control: #0d1a2b; --pm-border: var(--ns-n55); --pm-strong: var(--skin-neon); --pm-on-strong: #060b16; --pm-focus: var(--skin-pulse); --pm-line: var(--ns-n35); color: #e6fbff; font-family: var(--ns-sans); }
.rpg-pause-panel, #local-menu.rpg-pause-menu { padding: 0; overflow: hidden; border: 0; border-radius: 0; background: var(--ns-cut) 0 0 / 18px 18px no-repeat, var(--ns-cut) 100% 100% / 18px 18px no-repeat, var(--ns-scan), linear-gradient(rgba(57, 243, 255, .03) 1px, transparent 1px) 0 0 / 100% 28px, linear-gradient(90deg, rgba(57, 243, 255, .03) 1px, transparent 1px) 0 0 / 28px 100%, linear-gradient(160deg, rgba(7, 14, 26, .97), rgba(3, 6, 12, .98)); color: #e6fbff; box-shadow: inset 0 0 0 1px var(--ns-n55), 0 0 40px var(--ns-n20), 0 30px 90px rgba(0, 0, 0, .6); clip-path: polygon(18px 0, 100% 0, 100% calc(100% - 18px), calc(100% - 18px) 100%, 0 100%, 0 18px); backdrop-filter: blur(8px); outline: 0; }
.rpg-pause-panel { width: min(1240px, 100%); }
.rpg-pause-panel > .rpg-pause-menu { display: grid; grid-template-columns: auto minmax(0, 1fr) auto auto; grid-template-rows: auto minmax(0, 1fr) auto; grid-template-areas: "title where foot close" "book book book book" "nav nav nav nav"; column-gap: 16px; row-gap: 0; padding: 0; background: none; }
.rpg-pause-panel .pm-header > div:first-child { grid-area: title; align-self: center; display: flex; align-items: baseline; gap: 10px; padding: 12px 0 12px 26px; }
.pm-header small { display: block; margin: 0; color: var(--skin-pulse); font: 700 11px/1 var(--ns-mono); letter-spacing: .3em; }
.pm-header small::after { margin-left: 10px; color: var(--ns-n55); content: "//"; }
.pm-header h2 { margin: 0; color: #f2feff; font: 900 21px/1.2 var(--ns-sans); letter-spacing: .08em; text-shadow: 0 0 2px #fff, 0 0 12px color-mix(in srgb, var(--skin-neon) 70%, transparent); }
.rpg-pause-panel .pm-where { grid-area: where; align-self: center; justify-self: start; display: inline-flex; align-items: center; gap: 6px; max-width: 100%; margin: 0; padding: 4px 10px; overflow: hidden; border: 0; border-radius: 0; background: rgba(57, 243, 255, .08); color: var(--skin-neon); font: 700 12px/1.3 var(--ns-mono); letter-spacing: .08em; text-overflow: ellipsis; white-space: nowrap; box-shadow: inset 0 0 0 1px var(--ns-n35); }
.rpg-pause-panel .pm-where svg { width: 13px; height: 13px; color: var(--skin-pulse); }
.rpg-pause-panel .pm-close { grid-area: close; align-self: center; justify-self: end; display: grid; place-items: center; width: 38px; height: 38px; min-height: 38px; margin: 0 22px 0 0; padding: 0; color: var(--skin-neon); }
.pm-close::before, .pm-close::after { display: none; }
.pm-close svg { display: block; width: 18px; height: 18px; }
/* 細標題列底下一條霓虹線。 */
.rpg-pause-panel .pm-header::after { display: none; }
.rpg-pause-panel .pm-content { grid-area: book; position: relative; min-width: 0; min-height: 0; overflow: auto; margin: 0; padding: 20px 26px 18px; border: 0; border-top: 1px solid var(--ns-n35); border-bottom: 1px solid var(--ns-n35); border-radius: 0; background: radial-gradient(ellipse 60% 70% at 0% 0%, rgba(57, 243, 255, .06), transparent 70%); color: #e6fbff; box-shadow: none; scrollbar-gutter: auto; scrollbar-width: thin; scrollbar-color: var(--ns-n55) transparent; }
/* 底部工作列：一排圖示，目前的那格底下亮一條線。 */
.rpg-pause-panel .pm-nav { grid-area: nav; display: flex; flex-direction: row; align-items: center; justify-content: center; gap: 4px; min-width: 0; margin: 0; padding: 8px 18px 10px; overflow-x: auto; overflow-y: hidden; border: 0; background: linear-gradient(180deg, rgba(57, 243, 255, .05), rgba(2, 5, 11, .6)); scrollbar-width: none; }
.rpg-pause-panel .pm-nav .pm-nav-label { display: none; }
.rpg-pause-panel .pm-tiles { display: flex; flex-direction: row; align-items: stretch; justify-content: center; gap: 4px; }
.rpg-pause-panel .pm-nav button.pm-tile { position: relative; flex: none; flex-direction: column; justify-content: center; gap: 4px; width: 86px; min-width: 0; min-height: 58px; padding: 6px 4px 8px; border: 0; border-radius: 0; background: transparent; color: #a9d6de; font: 600 12px/1.2 var(--ns-sans); letter-spacing: .04em; white-space: nowrap; box-shadow: none; text-shadow: none; transform: none; transition: background .15s, color .15s; }
.rpg-pause-panel .pm-nav button.pm-tile::before { display: none; }
.rpg-pause-panel .pm-nav button.pm-tile::after { position: absolute; left: 22px; right: 22px; bottom: 2px; height: 2px; background: var(--skin-neon); box-shadow: 0 0 10px var(--skin-neon); content: ""; opacity: 0; transition: opacity .15s, left .2s, right .2s; }
.rpg-pause-panel .pm-tile .pm-tile-icon { display: grid; place-items: center; width: 34px; height: 30px; color: var(--skin-neon); }
.rpg-pause-panel .pm-nav button.pm-tile svg { width: 20px; height: 20px; color: inherit; }
.rpg-pause-panel .pm-nav button.pm-tile:hover { background: rgba(57, 243, 255, .08); color: #f2feff; transform: none; }
.rpg-pause-panel .pm-nav button.pm-tile[aria-current="page"] { background: linear-gradient(180deg, transparent, rgba(57, 243, 255, .16)); color: #f2feff; box-shadow: none; text-shadow: 0 0 8px color-mix(in srgb, var(--skin-neon) 60%, transparent); transform: none; }
.rpg-pause-panel .pm-nav button.pm-tile[aria-current="page"] .pm-tile-icon { background: var(--ns-brackets); filter: drop-shadow(0 0 6px var(--skin-neon)); }
.rpg-pause-panel .pm-nav button.pm-tile[aria-current="page"]::after { left: 10px; right: 10px; opacity: 1; }
.rpg-pause-panel .pm-nav button.pm-tile:focus-visible { outline: 2px solid var(--skin-pulse); outline-offset: -2px; }
.rpg-pause-panel .pm-nav button.pm-tile:active { background: rgba(255, 63, 180, .16); }
/* 內頁共用。 */
.pm-content :is(h2, h3, h4, p, span, b, strong, dd, li, label, em, output) { text-shadow: none; }
.pm-content :is(h3, b, strong, dd) { color: #f2feff; }
.pm-content :is(p, span, li, label, em) { color: #e6fbff; }
.pm-content :is(small, dt), .pm-location { color: #a9d6de; }
.pm-page-title { display: flex; align-items: center; gap: 10px; margin: 0 0 14px; color: #f2feff; font: 800 19px/1.3 var(--ns-sans); letter-spacing: .06em; }
.pm-page-title::before { color: var(--skin-pulse); content: ">"; font-family: var(--ns-mono); }
.pm-page-title::after, .pm-content .pm-hero h3::after { flex: 1; height: 1px; background: linear-gradient(90deg, var(--ns-n55), transparent); content: ""; }
.pm-section-title, .rpg-pause-menu .vn2-settings-body h4 { display: flex; align-items: center; flex-wrap: wrap; gap: 4px 8px; margin: 0 0 8px; color: var(--skin-neon); font: 700 12px/1.3 var(--ns-mono); letter-spacing: .2em; }
.rpg-pause-menu :is(.pm-section-title, .vn2-settings-body h4)::before { flex: none; width: 6px; height: 6px; background: var(--skin-pulse); content: ""; transform: none; }
.pm-section-title small { color: #a9d6de; font-size: 11px; letter-spacing: .04em; }
/* 角色狀態：三欄——全像投影的立繪、生命與能力、夥伴與紀錄，1280×720 一頁放得下。 */
.rpg-pause-panel .pm-content[data-page="status"] { display: grid; grid-template-columns: minmax(200px, 250px) minmax(0, 1fr) minmax(0, 1fr); grid-template-rows: auto auto minmax(0, 1fr); grid-template-areas: "figure card party" "figure card facts" "figure card attrs"; align-content: start; column-gap: 26px; row-gap: 14px; }
.rpg-pause-panel .pm-content[data-page="status"] > * { grid-column: 2 / -1; min-width: 0; margin: 0; }
.rpg-pause-panel .pm-content[data-page="status"] > .pm-hero { display: contents; }
.rpg-pause-panel .pm-content[data-page="status"] > .pm-party { grid-area: party; }
