[data-page="status"] .pm-figure { grid-area: figure; position: relative; display: grid; grid-template-columns: minmax(0, 1fr); place-items: end center; align-self: stretch; min-width: 0; min-height: 300px; padding: 20px 10px 26px; background: radial-gradient(ellipse 50% 12% at 50% 94%, color-mix(in srgb, var(--skin-neon) 45%, transparent), transparent 70%), repeating-linear-gradient(180deg, rgba(57, 243, 255, .06) 0 1px, transparent 1px 4px), radial-gradient(ellipse 60% 55% at 50% 60%, rgba(57, 243, 255, .1), transparent 72%), var(--ns-brackets); }
