.pm-stat, .pm-gear-skill { gap: 8px; padding: 8px 10px; border: 0; border-radius: 0; background: rgba(13, 26, 43, .85); color: #e6fbff; box-shadow: inset 0 0 0 1px var(--ns-n35), inset 2px 0 0 var(--skin-neon); }
.rpg-pause-menu :is(.pm-stat, .pm-gear-skill) > svg { color: var(--skin-neon); }
