.rpg-pause-menu button.pm-slot-frame:is(:hover, :focus-visible):not(:disabled) .pm-diamond, .pm-slot:is([data-state="match"], [data-state="target"]) .pm-diamond { background: var(--skin-pulse); box-shadow: none; transform: none; }
.rpg-pause-menu button.pm-slot-frame:is(:hover, :focus-visible):not(:disabled) .pm-diamond::before, .pm-slot:is([data-state="match"], [data-state="target"]) .pm-diamond::before { background: radial-gradient(circle, rgba(57, 243, 255, .32), #02050b 75%); }
