.rpg-pause-menu button.pm-bag-item:is(:hover, :focus-visible):not(:disabled) { background: color-mix(in srgb, var(--skin-neon) 18%, #0d1a2b); box-shadow: inset 0 0 0 1px var(--skin-neon); }
