.rpg-pause-menu :is(.pm-worn-mark, .pm-worn-mark small) { color: var(--skin-neon) !important; }
.pm-gear-note { border-left: 2px solid var(--skin-pulse); border-radius: 0; background: rgba(13, 26, 43, .8); color: #a9d6de; font-family: var(--ns-mono); }
.pm-gear-note b { color: #f2feff !important; }
/* 系統設定：一行一行的資料讀數。 */
.rpg-pause-menu .vn2-menu-row { min-height: 44px; padding: 8px 10px 8px 14px; border: 0; border-bottom: 1px dashed var(--ns-n20); border-radius: 0; background: transparent; color: #cdeff5; box-shadow: inset 2px 0 0 var(--ns-n35); }
