.pm-footer::before, .pm-footer::after { display: none; }
.pm-footer p { color: #a9d6de; font: 12px/1.4 var(--ns-mono); }
.rpg-pause-menu kbd { margin-right: 6px; padding: 2px 6px; border: 0; border-radius: 0; background: #0d1a2b; color: var(--skin-neon); font: 700 11px var(--ns-mono); box-shadow: inset 0 0 0 1px var(--ns-n55); }
button.pm-primary { min-height: 38px; padding: 0 18px; border: 0; border-radius: 0; background: var(--skin-neon); color: #060b16; font: 800 14px/1 var(--ns-mono); letter-spacing: .14em; clip-path: polygon(10px 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%, 0 10px); box-shadow: none; text-shadow: none; }
