@media (max-width: 680px) {
  .rpg-pause-panel > .rpg-pause-menu { grid-template-columns: minmax(0, 1fr) auto; grid-template-rows: auto auto minmax(0, 1fr) auto; grid-template-areas: "title close" "where foot" "book book" "nav nav"; column-gap: 8px; }
