}

/* ── 戰鬥：四個角落的 HUD ── */
.rpg-battle { --ink: #e6fbff !important; --muted: #a9d6de !important; --gold: var(--skin-neon) !important; --danger: #ff8fd0 !important; --bt-panel: rgba(8, 16, 30, .95) !important; --bt-panel-2: rgba(4, 7, 14, .93) !important; --bt-panel-soft: rgba(4, 7, 14, .82) !important; --bt-shade: 2 5 11 !important; --bt-edge: var(--skin-neon) !important; --bt-edge-soft: var(--ns-n35) !important; --bt-deep: #02050b !important; --bt-well-a: #12304a !important; --bt-well-b: #060b16 !important; --bt-track: #02050b !important; --bt-orb-a: #10233a !important; --bt-orb-b: #050a14 !important; --bt-orb-ink: #e6fbff !important; --bt-orb-glyph: var(--skin-neon) !important; --bt-orb-hover-a: #16405e !important; --bt-orb-hover-b: #0a1a2b !important; --bt-orb-off-a: #0b1018 !important; --bt-orb-off-ink: #93a3a8 !important; --bt-orb-off-edge: #3c4a50 !important; --bt-radius: 0px !important; --bt-blur: 4px !important; --bt-font: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace !important; --ns-top: 280px; --ns-dock: 160px; }
/* 上方保留一條給指令終端機與隊伍資料，戰場上的角色不會站到那裡；遭遇資訊實際顯示在左下角。 */
.battle-top { left: 0; right: 0; top: 0; display: block; height: var(--ns-top); padding: 0; background: linear-gradient(180deg, rgba(2, 5, 11, .55), transparent); }
.battle-top::before { position: fixed; left: 18px; bottom: 16px; z-index: 3; width: min(440px, calc(100% - 36px)); height: 120px; background: var(--ns-scan), var(--ns-panel); box-shadow: inset 0 0 0 1px var(--ns-n55), inset 3px 0 0 var(--skin-pulse); clip-path: polygon(14px 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%, 0 14px); content: ""; }
.battle-top > * { position: fixed; z-index: 4; left: 36px; max-width: min(400px, calc(100% - 72px)); margin: 0; }
.battle-caption { bottom: 108px; color: var(--skin-pulse); font-size: 11px; letter-spacing: .3em; }
.battle-caption::before { margin-right: 6px; color: var(--skin-neon); content: "!"; }
.rpg-battle.is-boss .battle-caption { color: #ff8fd0; }
.battle-top h2 { bottom: 68px; overflow: hidden; color: #f2feff; font: 900 24px/1.3 var(--ns-sans); letter-spacing: .04em; text-overflow: ellipsis; white-space: nowrap; text-shadow: 0 0 2px #fff, 0 0 14px color-mix(in srgb, var(--skin-neon) 70%, transparent); }
.battle-turn { left: auto; right: max(36px, calc(100% - 442px)); bottom: 108px; padding: 1px 6px; background: var(--skin-neon); color: #060b16; font-size: 11px; font-weight: 800; letter-spacing: .1em; text-shadow: none; }
.battle-turn.is-hurry { background: var(--skin-pulse); }
.battle-log { bottom: 24px; max-height: 3em; overflow: hidden; color: #cdeff5; font-size: 14px; line-height: 1.5; text-shadow: none; }
.battle-log::before { color: var(--skin-pulse); content: "> "; }
/* 右上：隊伍資料面板；奧義條在面板最下面，整條看得到。 */
.battle-dock { left: 0; right: 0; bottom: 0; display: block; height: var(--ns-dock); padding: 0; background: none; }
.battle-party, .battle-party[data-size] { position: fixed; top: 14px; right: 76px; z-index: 5; display: grid; grid-template-columns: repeat(var(--members, 1), minmax(0, 230px)); gap: 6px 8px; width: auto; max-width: calc(100% - 96px); padding: 24px 10px 10px; background: var(--ns-scan), var(--ns-panel); box-shadow: inset 0 0 0 1px var(--ns-n55), 0 0 22px var(--ns-n20); clip-path: polygon(0 0, calc(100% - 14px) 0, 100% 14px, 100% 100%, 14px 100%, 0 calc(100% - 14px)); }
.battle-party[data-size='1'] { grid-template-columns: minmax(0, 300px); }
.battle-party::before { position: absolute; left: 12px; top: 7px; color: var(--skin-pulse); content: "PARTY // LINK"; font: 700 10px/1 var(--ns-mono); letter-spacing: .26em; }
.battle-member { display: grid; grid-template-columns: 46px minmax(0, 1fr); align-items: center; gap: 0 10px; min-width: 0; padding: 6px 8px 6px 6px; border: 0; border-radius: 0; background: rgba(13, 26, 43, .8); box-shadow: inset 2px 0 0 var(--ns-n35); backdrop-filter: none; clip-path: none; transform: none; }
.battle-member::before { display: none; }
.battle-member[aria-current="true"] { background: linear-gradient(90deg, rgba(57, 243, 255, .16), rgba(13, 26, 43, .85)); box-shadow: inset 3px 0 0 var(--skin-neon), 0 0 14px var(--ns-n35); transform: none; }
.battle-member-face, .battle-party:not([data-size='1']) .battle-member-face { display: grid; place-items: center; width: 46px; height: 46px; padding: 3px; background: var(--ns-brackets), #02050b; }
.battle-member .battle-portrait, .battle-party:not([data-size='1']) .battle-portrait { width: 40px; height: 40px; border: 0; border-radius: 0; background: none; box-shadow: none; object-fit: cover; object-position: 50% 12%; }
.battle-member .battle-face, .battle-party:not([data-size='1']) .battle-face { width: 40px; height: 32px; border: 0; border-radius: 0; background: none; box-shadow: none; }
.battle-member-body { gap: 1px 8px; }
.battle-member-name, .battle-party:not([data-size='1']) .battle-member-name { margin: 0 0 2px; color: #f2feff; font: 800 14px/1.2 var(--ns-sans); letter-spacing: .04em; }
.battle-member[aria-current="true"] .battle-member-name::before { color: var(--skin-neon); content: "▶ "; }
.battle-stat small { color: #a9d6de; font-size: 10px; }
.battle-stat b, .battle-party:not([data-size='1']) .battle-stat b { color: var(--skin-neon); font-size: 15px; }
.battle-mp-value b, .battle-party:not([data-size='1']) .battle-mp-value b { color: #c3c9ff; font-size: 13px; }
.battle-member .battle-bar, .battle-limit-box .battle-bar.limit { height: 7px; border-radius: 0; background: #02050b; box-shadow: inset 0 0 0 1px var(--ns-n35); }
.battle-member .battle-bar i { border-radius: 0; background: repeating-linear-gradient(90deg, transparent 0 6px, #02050b 6px 7px), linear-gradient(90deg, var(--skin-neon), #b8fbff); }
.battle-member .battle-bar.mp { height: 5px; }
.battle-member .battle-bar.mp i { background: linear-gradient(90deg, #6f7dff, #b9c1ff); }
.battle-member.is-low .battle-bar.hp i { background: repeating-linear-gradient(90deg, transparent 0 6px, #02050b 6px 7px), linear-gradient(90deg, var(--skin-pulse), #ffb3dd); }
.battle-member-down { color: #ff8fd0; }
.battle-limit-box { grid-column: 1 / -1; display: grid; grid-template-columns: auto minmax(0, 1fr); align-items: center; gap: 10px; margin: 0; padding: 4px 4px 0; border: 0; background: none; clip-path: none; box-shadow: none; }
.battle-limit-value { color: var(--skin-pulse); font-size: 11px; font-weight: 700; letter-spacing: .12em; }
.battle-limit-box .battle-bar.limit i { border-radius: 0; background: repeating-linear-gradient(90deg, transparent 0 6px, #02050b 6px 7px), linear-gradient(90deg, var(--skin-pulse), var(--skin-neon)); }
/* 右下：鎖定目標。 */
.battle-command-area { position: fixed; right: 18px; bottom: 20px; z-index: 4; max-width: 34%; }
.battle-target-label { gap: 8px; padding: 8px 14px; border: 0; border-radius: 0; background: rgba(6, 11, 22, .94); color: var(--skin-neon); font-size: 13px; font-weight: 700; letter-spacing: .08em; box-shadow: inset 0 0 0 1px var(--ns-n55), inset -3px 0 0 var(--skin-pulse); clip-path: polygon(14px 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%, 0 14px); }
.battle-target-label::before { color: var(--skin-pulse); content: "LOCK"; font-size: 10px; letter-spacing: .2em; }
.battle-target-label .bt-glyph { color: var(--skin-pulse); }
/* 左上：指令終端機（在上方保留的那一條裡，不擋到角色）。一行一個指令，前面是 >，選到的那行後面有閃爍的游標。 */
.battle-actions.battle-ring:not([data-menu="result"]), .rpg-battle[data-layout] .battle-actions.battle-ring:not([data-menu="result"]) { left: 18px; right: auto; top: 14px; bottom: auto; display: grid; grid-template-columns: minmax(0, 1fr); align-content: start; gap: 2px; width: 230px; height: auto; max-height: calc(var(--ns-top) - 24px); margin: 0; padding: 30px 8px 10px; overflow-x: hidden; overflow-y: auto; border: 0; border-radius: 0; background: var(--ns-scan), var(--ns-panel); box-shadow: inset 0 0 0 1px var(--ns-n55), inset 3px 0 0 var(--skin-neon), 0 0 22px var(--ns-n20); transform: none; translate: none; clip-path: polygon(0 0, calc(100% - 14px) 0, 100% 14px, 100% 100%, 0 100%); animation: ns-term-in .3s steps(6, end) both; scrollbar-width: thin; scrollbar-color: var(--ns-n55) transparent; }
.battle-actions.battle-ring:is([data-menu="skills"], [data-menu="items"]), .rpg-battle[data-layout] .battle-actions.battle-ring:is([data-menu="skills"], [data-menu="items"]) { width: 336px; }
.battle-actions.battle-ring:not([data-menu="result"])::before { position: absolute; left: 12px; right: 12px; top: 9px; display: block; width: auto; height: auto; overflow: hidden; translate: none; border: 0; border-radius: 0; background: none; box-shadow: none; color: var(--skin-pulse); content: "CMD://" attr(aria-label); font: 700 10px/1.2 var(--ns-mono); letter-spacing: .2em; text-overflow: ellipsis; white-space: nowrap; animation: none; }
.battle-actions.battle-ring:not([data-menu="result"])::after { display: none; }
.battle-ring:not([data-menu="result"]) :is(.bt-orb, .bt-card), .rpg-battle[data-layout] .battle-ring:not([data-menu="result"]) .bt-orb { --orb: auto; position: relative; display: flex; align-items: center; justify-content: flex-start; gap: 8px; width: 100%; height: auto; min-height: 34px; margin: 0; padding: 3px 26px 3px 8px; border: 0; border-radius: 0; clip-path: none; background: transparent; color: #cdeff5; box-shadow: none; text-shadow: none; font: 700 16px/1.2 var(--ns-mono); letter-spacing: .06em; text-align: left; white-space: nowrap; translate: none; scale: none; transform: none; animation: none; }
.battle-ring:not([data-menu="result"]) .bt-orb::before { flex: none; width: auto; height: auto; margin: 0; background: none; color: var(--skin-pulse); content: ">"; }
.battle-ring:not([data-menu="result"]) .bt-orb::after { position: absolute; right: 8px; top: calc(50% - 8px); display: block; width: 8px; height: 16px; background: var(--skin-neon); content: ""; opacity: 0; }
.battle-ring :is(.bt-orb, .bt-card) span { max-width: none; overflow: hidden; text-overflow: ellipsis; }
.battle-ring :is(.bt-orb, .bt-card) .bt-glyph { flex: none; width: 18px; height: 18px; color: var(--skin-neon); }
.battle-ring :is(.bt-orb, .bt-card) .bt-glyph svg { width: 16px; height: 16px; }
.battle-ring:not([data-menu="result"]) :is(.bt-orb, .bt-card):is(:hover, :focus-visible):not(:disabled) { background: linear-gradient(90deg, rgba(57, 243, 255, .2), rgba(57, 243, 255, .04)); color: #fff; box-shadow: inset 2px 0 0 var(--skin-neon); scale: none; }
.battle-ring:not([data-menu="result"]) .bt-orb:is(:hover, :focus-visible):not(:disabled)::after { opacity: 1; animation: ns-blink 1s steps(2, end) infinite; }
.battle-ring :is(.bt-orb, .bt-card):focus-visible { outline: 1px solid var(--skin-pulse); outline-offset: -2px; }
.battle-ring :is(.bt-orb, .bt-card):active:not(:disabled) { background: color-mix(in srgb, var(--skin-pulse) 30%, #060b16); scale: none; }
.battle-ring :is(.bt-orb, .bt-card):disabled { background: transparent; color: #7f9196; box-shadow: none; text-decoration: line-through; text-decoration-color: rgba(127, 145, 150, .6); cursor: not-allowed; }
.battle-ring :is(.bt-orb, .bt-card):disabled .bt-glyph, .battle-ring .bt-orb:disabled::before { color: #7f9196; }
.battle-ring .bt-orb.is-attack { color: #f2feff; }
.battle-ring .bt-orb.battle-limit { background: linear-gradient(90deg, color-mix(in srgb, var(--skin-pulse) 40%, #060b16), rgba(57, 243, 255, .2)); color: #fff; white-space: normal; box-shadow: inset 0 0 0 1px var(--skin-pulse); animation: ns-pulse 1.2s ease-in-out infinite; }
.battle-ring .bt-orb.battle-limit span { white-space: normal; line-height: 1.3; }
.battle-ring .bt-orb.is-confirming { color: #ff8fd0; box-shadow: inset 2px 0 0 var(--skin-pulse); }
.battle-ring :is(.bt-orb, .bt-card) .bt-dmg, .rpg-battle[data-commands="list"] .battle-ring[data-menu="main"] .bt-orb .bt-dmg { position: static; flex: none; min-width: 0; margin-left: auto; padding: 1px 5px; border: 0; border-radius: 0; background: rgba(57, 243, 255, .14); color: var(--skin-neon); font-size: 11px; box-shadow: inset 0 0 0 1px var(--ns-n35); animation: none; }
.battle-ring:not([data-menu="result"]) .bt-card { padding-left: 18px; font-size: 14px; }
.battle-ring .bt-card::before { left: 6px; top: 8px; bottom: 8px; width: 3px; border-radius: 0; background: var(--fx, var(--skin-neon)); box-shadow: 0 0 6px var(--fx, var(--skin-neon)); }
.battle-ring:is([data-menu="skills"], [data-menu="items"]) .bt-orb { margin-top: 6px; border-top: 1px dashed var(--ns-n35); color: #a9d6de; font-size: 13px; }
.battle-ring:is([data-menu="skills"], [data-menu="items"]) .bt-orb::before { content: "<"; }
@keyframes ns-term-in { from { clip-path: polygon(0 0, 0 0, 0 0, 0 100%, 0 100%); } }
@keyframes ns-blink { 50% { opacity: 0; } }
@keyframes ns-pulse { 50% { box-shadow: inset 0 0 0 1px var(--skin-pulse), 0 0 16px color-mix(in srgb, var(--skin-pulse) 60%, transparent); } }
/* 敵人名牌、行動預告、輪到誰。 */
.battle-unit-label { padding: 4px 10px 5px; border: 0; border-radius: 0; background: rgba(6, 11, 22, .94); box-shadow: inset 0 0 0 1px var(--ns-n55), inset 0 2px 0 var(--skin-pulse); }
.battle-unit-label b { color: #f2feff; font: 700 14px/1.3 var(--ns-sans); }
.battle-unit-label small { color: #a9d6de; font-size: 10px; }
.battle-enemy .battle-bar { height: 5px; border-radius: 0; }
.battle-enemy .battle-bar i { background: linear-gradient(90deg, var(--skin-pulse), #ffb3dd); }
.battle-unit[aria-pressed="true"] .battle-unit-label { box-shadow: inset 0 0 0 1px var(--skin-neon), inset 0 2px 0 var(--skin-pulse), 0 0 16px var(--ns-n35); }
.battle-unit[aria-pressed="true"] .battle-unit-label::after { border: 0; border-radius: 0; background: var(--skin-pulse); color: #060b16; font-weight: 800; }
.rpg-battle :is(.bt-intent, .bt-turn-tag) { border: 0; border-radius: 0; background: rgba(6, 11, 22, .94); box-shadow: inset 0 0 0 1px var(--ns-n55); }
.bt-turn-tag::after { border-color: var(--skin-neon); background: #060b16; }
.bt-callout { color: #f2feff; font-family: var(--ns-sans); font-weight: 900; text-shadow: 0 0 2px #fff, 0 0 18px var(--skin-neon), 3px 0 0 color-mix(in srgb, var(--skin-pulse) 70%, transparent); }
/* 戰鬥結束與戰鬥中的對白。 */
.battle-result { padding: 28px 44px 24px; border: 0; border-radius: 0; background: var(--ns-scan), var(--ns-panel); box-shadow: inset 0 0 0 1px var(--skin-neon), 0 0 30px var(--ns-n35); clip-path: polygon(14px 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%, 0 14px); }
.battle-result small { color: var(--skin-pulse); letter-spacing: .4em; }
.battle-result h3 { color: #f2feff; font-family: var(--ns-sans); font-weight: 900; text-shadow: 0 0 2px #fff, 0 0 16px var(--skin-neon); }
.battle-result p { color: #cdeff5; }
.battle-actions.battle-ring[data-menu="result"] button { min-width: 180px; min-height: 44px; font-size: 16px; }
.bt-talk b { color: var(--skin-neon); font-family: var(--ns-mono); }
.bt-talk p { color: #e6fbff; }
@media (max-width: 600px) {
  .rpg-battle { --ns-top: 176px; --ns-dock: 340px; }
  .battle-party, .battle-party[data-size] { top: 10px; left: 10px; right: 58px; grid-template-columns: repeat(min(var(--members, 1), 2), minmax(0, 1fr)); max-width: none; }
  .battle-party[data-size='1'] { grid-template-columns: minmax(0, 1fr); }
  .battle-member { grid-template-columns: 38px minmax(0, 1fr); gap: 0 8px; }
  .battle-member-face, .battle-party:not([data-size='1']) .battle-member-face { width: 38px; height: 38px; }
  .battle-member .battle-portrait, .battle-party:not([data-size='1']) .battle-portrait { width: 32px; height: 32px; }
  .battle-top::before { left: 10px; right: 10px; bottom: 10px; width: auto; height: 104px; }
  .battle-top > * { left: 24px; max-width: calc(100% - 48px); }
  .battle-caption, .battle-turn { bottom: 90px; }
  .battle-top .battle-turn { left: auto; right: 24px; }
  .battle-top h2 { bottom: 56px; font-size: 19px; }
  .battle-log { bottom: 18px; font-size: 12px; }
  .battle-actions.battle-ring:not([data-menu="result"]), .rpg-battle[data-layout] .battle-actions.battle-ring:not([data-menu="result"]) { top: auto; bottom: 126px; width: 190px; max-height: 214px; }
  .battle-actions.battle-ring:is([data-menu="skills"], [data-menu="items"]), .rpg-battle[data-layout] .battle-actions.battle-ring:is([data-menu="skills"], [data-menu="items"]) { width: calc(100% - 36px); }
  .battle-ring:not([data-menu="result"]) :is(.bt-orb, .bt-card), .rpg-battle[data-layout] .battle-ring:not([data-menu="result"]) .bt-orb { min-height: 34px; font-size: 14px; }
}

/* ── 商店 ── */
.rpg-shop { clip-path: polygon(22px 0, 100% 0, 100% calc(100% - 22px), calc(100% - 22px) 100%, 0 100%, 0 22px); }
.rpg-shop[open] { grid-template-columns: minmax(0, 1fr); }
.rpg-shop > * { min-width: 0; }
.rpg-shop::backdrop { background: rgba(2, 4, 10, .65); }
.rpg-shop :is(.shop-head, .shop-foot, .shop-total) { border-color: var(--ns-n35); border-style: solid; }
.rpg-shop :is(h2, h3, b, output) { color: #f2feff; }
.rpg-shop .shop-price { color: var(--skin-neon); font-family: var(--ns-mono); }
.rpg-shop :is(small, .shop-note, .shop-foot, .shop-qty > span, .shop-empty, .shop-toast) { color: #a9d6de; }
.rpg-shop .shop-wallet { border: 1px solid var(--skin-neon); border-radius: 0; background: #060b16; color: #e6fbff; box-shadow: none; }
.rpg-shop .shop-wallet b { color: var(--skin-neon); font-family: var(--ns-mono); }
.rpg-shop :is(.shop-wallet span, .shop-art span) { border: 1px solid var(--ns-n35); border-radius: 0; background: #02050b; }
.rpg-shop .shop-row { border: 0; border-radius: 0; background: rgba(13, 26, 43, .8); color: #e6fbff; box-shadow: inset 2px 0 0 var(--ns-n35); }
.rpg-shop .shop-row:hover { background: color-mix(in srgb, var(--skin-neon) 12%, #0d1a2b); }
.rpg-shop .shop-row[aria-selected="true"] { background: linear-gradient(90deg, color-mix(in srgb, var(--skin-neon) 24%, #0d1a2b), rgba(13, 26, 43, .8)); box-shadow: inset 4px 0 0 var(--skin-pulse), 0 0 12px var(--ns-n20); }
.rpg-shop .shop-detail { box-shadow: inset 0 0 0 1px var(--ns-n35); }
.rpg-shop .shop-list { border-radius: 0; }
.rpg-shop .shop-list:focus-visible { outline: 2px solid var(--skin-pulse); outline-offset: 2px; }
.rpg-shop .shop-short { color: #ff8fd0; }
.rpg-shop kbd { border-color: var(--ns-n35); border-radius: 0; background: #060b16; color: #e6fbff; }

/* ── 取名 ── */
.rpg-naming { overflow: visible; }
.rpg-naming .naming-body { grid-template-columns: minmax(0, 1fr); }
.rpg-naming .naming-face { border: 1px solid var(--skin-neon); border-radius: 0; background: #060b16; clip-path: polygon(25% 0, 75% 0, 100% 50%, 75% 100%, 25% 100%, 0 50%); box-shadow: none; }
.rpg-naming small { color: var(--skin-pulse); font-family: var(--ns-mono); letter-spacing: .3em; }
.rpg-naming h2 { color: #f2feff; font-family: var(--ns-sans); }
.rpg-naming input { border: 0; border-radius: 0; background: #02050b; color: #f2feff; box-shadow: inset 0 0 0 1px var(--skin-neon); font-family: var(--ns-mono); }
.rpg-naming .naming-note { color: #a9d6de; }

/* ── 轉盤 ── */
#wheel .wheel-stage { --accent: var(--skin-neon) !important; --on-accent: #060b16 !important; }
#wheel .wheel-dial { background: repeating-conic-gradient(from calc(var(--span) / -2 - 1deg), var(--skin-pulse) 0 1deg, #050a14 1deg var(--span)); box-shadow: 0 0 0 6px #02050b, 0 0 0 7px var(--skin-neon), 0 0 34px color-mix(in srgb, var(--skin-neon) 40%, transparent), 0 24px 70px rgba(0, 0, 0, .8); }
#wheel :is(.wheel-title, .wheel-name, .wheel-keys, .wheel-cancel) { border: 1px solid var(--skin-neon); border-radius: 0; background: #060b16; color: #e6fbff; box-shadow: 0 0 12px var(--ns-n35); font-family: var(--ns-mono); }
@media (prefers-reduced-motion: reduce) { .battle-actions.battle-ring, .battle-ring .bt-orb::after, .battle-ring .bt-orb.battle-limit { animation: none !important; } .rpg-pause-panel .pm-nav button.pm-tile, .rpg-pause-panel .pm-nav button.pm-tile::after { transition: none; } }
/* ── 多人連線：頻道燈號是終端機的狀態列、聊天一行行跑在面板上、按鈕與右上角的關閉鍵是切角的方鍵 ── */
.mp-chip, .mp-follow, .mp-duel { border: 0; border-radius: 0; background: rgba(13, 26, 43, .92); color: #e6fbff; box-shadow: inset 0 0 0 1px var(--ns-n55); text-shadow: none; font-family: var(--ns-mono); letter-spacing: .08em; transform: none; clip-path: polygon(14px 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%, 0 14px); padding: 6px 14px; }
.mp-tool { border: 0; border-radius: 0; background: rgba(13, 26, 43, .92); color: #e6fbff; box-shadow: inset 0 0 0 1px var(--ns-n55); text-shadow: none; font-family: var(--ns-mono); letter-spacing: .08em; transform: none; border-radius: 0; }
.mp-chip:is(:hover, :focus-visible), .mp-tool:is(:hover, :focus-visible) { background: var(--skin-neon); color: #060b16; text-shadow: none; outline: none; }
.mp-line { border: 0; border-radius: 0; background: var(--ns-panel); color: #e6fbff; box-shadow: inset 0 0 0 1px var(--ns-n55), inset 3px 0 0 var(--skin-neon); backdrop-filter: blur(6px); padding: 4px 10px; border-radius: 0; font-family: var(--ns-mono); font-size: 12px; letter-spacing: .02em; }
.mp-line b { color: var(--skin-neon); }
.mp-line b::before { content: "> "; color: var(--skin-pulse); }
.mp-line.mine b { color: var(--skin-pulse); }
.mp-line.system { color: #a9d6de; font-style: normal; }
.mp-line.dm { box-shadow: inset 0 0 0 1px var(--ns-n55), inset 3px 0 0 #c77dff; }
.mp-line.dm b { color: #e2b8ff; }
.mp-ui.composing .mp-log { background: rgba(6, 11, 22, .72); box-shadow: inset 0 0 0 1px var(--ns-n35); }
.mp-input { border: 0; border-radius: 0; background: rgba(13, 26, 43, .92); color: #e6fbff; box-shadow: inset 0 0 0 1px var(--ns-n55); text-shadow: none; font-family: var(--ns-mono); letter-spacing: .08em; transform: none; font-family: var(--ns-mono); }
.mp-send { border: 0; border-radius: 0; background: rgba(13, 26, 43, .92); color: #e6fbff; box-shadow: inset 0 0 0 1px var(--ns-n55); text-shadow: none; font-family: var(--ns-mono); letter-spacing: .08em; transform: none; background: var(--skin-neon); color: #060b16; }
.mp-emotes { border: 0; border-radius: 0; background: var(--ns-panel); color: #e6fbff; box-shadow: inset 0 0 0 1px var(--ns-n55), inset 3px 0 0 var(--skin-neon); backdrop-filter: blur(6px); }
.mp-badge { border-radius: 0; background: var(--skin-pulse); color: #060b16; box-shadow: none; }
.mp-tag { border-radius: 0; background: rgba(6, 11, 22, .88); color: #e6fbff; box-shadow: inset 0 0 0 1px var(--skin-neon); text-shadow: none; font-family: var(--ns-mono); }
[data-larch-ui="close"] { border: 0; border-radius: 0; background: rgba(13, 26, 43, .92); color: #e6fbff; box-shadow: inset 0 0 0 1px var(--ns-n55); text-shadow: none; font-family: var(--ns-mono); letter-spacing: .08em; transform: none; border-radius: 0; clip-path: polygon(14px 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%, 0 14px); }
[data-larch-ui="close"]:is(:hover, :focus-visible) { background: var(--skin-neon); color: #060b16; text-shadow: none; }
/* 同行的夥伴：點一下在上面看他的資料。 */
button.pm-party-member[data-joined]:is(:hover, :focus-visible) { background: rgba(20, 44, 70, .95); color: #e6fbff; }
button.pm-party-member[aria-current="true"] { box-shadow: inset 0 0 0 1px var(--skin-neon), inset 4px 0 0 var(--skin-neon), 0 0 14px color-mix(in srgb, var(--skin-neon) 40%, transparent); }

