/* @larch-params {
  "neon": { "type": "color", "label": "霓虹主色", "labelEn": "Neon", "default": "#39f3ff" },
  "pulse": { "type": "color", "label": "第二色", "labelEn": "Second neon", "default": "#ff3fb4" },
  "open": { "type": "audio", "kind": "sfx", "label": "開啟視窗音效", "labelEn": "Window open sound", "default": "/skills/neon-signal/sfx/open.mp3" },
  "close": { "type": "audio", "kind": "sfx", "label": "關閉視窗音效", "labelEn": "Window close sound", "default": "/skills/neon-signal/sfx/close.mp3" },
  "tab": { "type": "audio", "kind": "sfx", "label": "切換分頁音效", "labelEn": "Tab switch sound", "default": "/skills/neon-signal/sfx/press.mp3" },
  "hover": { "type": "audio", "kind": "sfx", "label": "按鈕滑過音效", "labelEn": "Button hover sound", "default": "/skills/neon-signal/sfx/hover.mp3" }
} */
:scope[data-larch-ui="toolbar"] button { color: #cdf7ff; font: 600 12px/1 ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; letter-spacing: .12em; text-shadow: 0 0 6px rgba(0, 0, 0, .9); }
:scope[data-larch-ui="toolbar"] button::after { background: var(--skin-neon); box-shadow: 0 0 6px var(--skin-neon); }
:scope[data-larch-ui="toolbar"] button:hover, :scope[data-larch-ui="toolbar"] button:focus-visible, :scope[data-larch-ui="toolbar"] button[aria-pressed="true"], :scope[data-larch-ui="toolbar"] button[aria-expanded="true"] { color: var(--skin-neon); }
:scope[data-larch-ui="toolbar"] button:focus-visible { outline-color: var(--skin-neon); }
:scope[data-larch-ui="toolbar"] button:disabled { color: #7d8c91; }
:scope[data-larch-ui="toolbar"] .vn2-dialogue-actions-divider { background: color-mix(in srgb, var(--skin-neon) 60%, transparent); }
:scope[data-larch-ui="settings"] { --vn-settings-surface: #060b16 !important; --vn-settings-accent: var(--skin-neon) !important; --vn-settings-text: #e6fbff !important; --vn-settings-button: #0d1a2b !important; --vn-settings-button-text: #e6fbff !important; --vn-settings-border: color-mix(in srgb, var(--skin-neon) 45%, transparent) !important; }
:scope[data-larch-ui="history"] { --vn-history-surface: #060b16 !important; --vn-history-text: #e6fbff !important; --vn-history-speaker: var(--skin-neon) !important; --vn-history-accent: var(--skin-pulse) !important; --vn-history-muted: #93a3a8 !important; --vn-history-border: #1d3b4a !important; }
:scope:is([data-larch-ui="settings"], [data-larch-ui="save"], [data-larch-ui="history"]) { border-radius: 0; background: repeating-linear-gradient(180deg, rgba(255, 255, 255, .022) 0 1px, transparent 1px 3px), linear-gradient(160deg, rgba(8, 16, 30, .97), rgba(4, 7, 14, .98)); color: #e6fbff; clip-path: polygon(22px 0, 100% 0, 100% calc(100% - 22px), calc(100% - 22px) 100%, 0 100%, 0 22px); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--skin-neon) 50%, transparent); font-family: "Noto Sans TC", "PingFang TC", "Microsoft JhengHei", system-ui, sans-serif; }
:scope > header { border-bottom: 1px solid color-mix(in srgb, var(--skin-neon) 35%, transparent); background: transparent; }
:scope > header small { color: var(--skin-pulse); font-family: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; letter-spacing: .3em; }
:scope > header h2 { color: #f2feff; text-shadow: 0 0 12px color-mix(in srgb, var(--skin-neon) 60%, transparent); }
:scope > header h2::after { margin-left: 4px; color: var(--skin-neon); content: "_"; font-family: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; animation: ns-blink 1.1s steps(2, end) infinite; }
