:scope > header button:focus-visible { outline: 2px solid var(--skin-pulse); outline-offset: 3px; }
:scope > header button:active { background: color-mix(in srgb, var(--skin-neon) 70%, #fff); color: #060b16; }
@keyframes ns-blink { 50% { opacity: 0; } }
/* 設定：分頁是終端機上方一排 [分頁]，選中的那個底下亮一條游標線；每一列是一行資料讀數。 */
:scope[data-larch-ui="settings"] { width: min(720px, 100%); }
