[data-larch-ui="settings-tab"][aria-selected="true"]::after { opacity: 1; transform: none; }
[data-larch-ui="settings-tab"][aria-selected="true"] span { position: relative; }
[data-larch-ui="settings-tab"][aria-selected="true"]::before { position: absolute; right: 4px; top: 50%; width: 6px; height: 13px; margin-top: -7px; background: var(--skin-neon); content: ""; animation: ns-blink 1.1s steps(2, end) infinite; }
[data-larch-ui="settings-tab"]:focus-visible { outline: 2px solid var(--skin-pulse); outline-offset: -3px; }
[data-larch-ui="settings-tab"]:active { background: rgba(255, 63, 180, .14); }
