[data-larch-ui="settings-body"] { padding: 16px 20px 22px; scrollbar-width: thin; scrollbar-color: color-mix(in srgb, var(--skin-neon) 50%, transparent) transparent; }
[data-larch-ui="settings-panel"] { gap: 2px; counter-reset: ns-row; }
:scope[data-larch-ui="settings"] .vn2-menu-row { counter-increment: ns-row; position: relative; min-height: 46px; gap: 14px; padding: 8px 8px 8px 44px; border: 0; border-bottom: 1px dashed color-mix(in srgb, var(--skin-neon) 22%, transparent); border-radius: 0; background: transparent; color: #cdeff5; font-size: 14px; box-shadow: none; transform: none; }
:scope[data-larch-ui="settings"] .vn2-menu-row::before { position: absolute; left: 6px; top: 50%; color: color-mix(in srgb, var(--skin-pulse) 80%, #fff); content: counter(ns-row, decimal-leading-zero); font: 700 11px/1 ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; letter-spacing: .04em; transform: translateY(-50%); }
:scope[data-larch-ui="settings"] .vn2-menu-row::after { position: absolute; left: 26px; top: 50%; color: color-mix(in srgb, var(--skin-neon) 70%, transparent); content: ">"; font: 700 12px/1 ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; transform: translateY(-50%); }
:scope[data-larch-ui="settings"] .vn2-menu-row:hover { background: linear-gradient(90deg, rgba(57, 243, 255, .1), transparent 75%); color: #fff; transform: none; }
:scope[data-larch-ui="settings"] .vn2-menu-row:focus-within { background: linear-gradient(90deg, rgba(57, 243, 255, .14), transparent 80%); box-shadow: inset 2px 0 0 var(--skin-neon); }
:scope[data-larch-ui="settings"] .vn2-menu-row > span { color: inherit; font-weight: 600; letter-spacing: .04em; }
