:scope[data-larch-ui="settings"] .vn2-menu-row b::before { color: #8fb9c1; content: "[ "; }
:scope[data-larch-ui="settings"] .vn2-menu-row b::after { color: #8fb9c1; content: " ]"; }
:scope[data-larch-ui="settings"] .vn2-menu-row select { min-height: 34px; padding: 0 10px; border: 1px solid color-mix(in srgb, var(--skin-neon) 55%, transparent); border-radius: 0; background: #02050b; color: #e6fbff; font: 600 13px ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; }
:scope[data-larch-ui="settings"] .vn2-menu-row select option { background: #02050b; color: #e6fbff; }
