:scope[data-larch-ui="settings"] .vn2-reading-note::before { color: var(--skin-pulse); content: "// "; font-family: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; }
:scope[data-larch-ui="settings"] .vn2-reading-reset { justify-self: start; min-height: 38px; padding: 0 16px 0 44px; border: 1px solid color-mix(in srgb, var(--skin-neon) 55%, transparent); color: #e6fbff; cursor: pointer; }
:scope[data-larch-ui="settings"] .vn2-reading-reset:hover:not(:disabled), :scope[data-larch-ui="settings"] .vn2-reading-reset:focus-visible { background: var(--skin-neon); color: #060b16; }
