:scope[data-larch-ui="settings"] .vn2-menu-actions button { min-height: 42px; border: 0; border-radius: 0; background: #0d1a2b; color: #e6fbff; font-family: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; letter-spacing: .1em; box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--skin-neon) 55%, transparent); }
:scope[data-larch-ui="settings"] .vn2-menu-actions button svg { color: var(--skin-neon); }
:scope[data-larch-ui="settings"] .vn2-menu-actions button:hover, :scope[data-larch-ui="settings"] .vn2-menu-actions button:focus-visible { background: var(--skin-neon); color: #060b16; }
:scope[data-larch-ui="settings"] .vn2-menu-actions button:hover svg, :scope[data-larch-ui="settings"] .vn2-menu-actions button:focus-visible svg { color: #060b16; }
:scope[data-larch-ui="settings"] .vn2-menu-actions button:focus-visible { outline: 2px solid var(--skin-pulse); outline-offset: 2px; }
/* 存讀檔：一格一格記憶體區塊。 */
[data-larch-ui="save-slot"] { min-height: 158px; border-radius: 0; background: #060b16; clip-path: polygon(14px 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%, 0 14px); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--skin-neon) 45%, transparent); }
[data-larch-ui="save-slot"] figure { border-radius: 0; background: radial-gradient(ellipse 80% 70% at 50% 35%, rgba(57, 243, 255, .1), transparent 70%), linear-gradient(rgba(57, 243, 255, .05) 1px, transparent 1px) 0 0 / 100% 14px, #070d18; color: color-mix(in srgb, var(--skin-neon) 60%, #93a3a8); }
[data-larch-ui="save-slot"] figure::after { background: linear-gradient(180deg, transparent 30%, rgba(4, 7, 14, .92) 78%); }
[data-larch-ui="save-slot"] .save-slot-info { padding-top: 30px; }
