[data-larch-ui="save-slot"]:hover { box-shadow: inset 0 0 0 1px var(--skin-neon), 0 0 18px color-mix(in srgb, var(--skin-neon) 30%, transparent); }
[data-larch-ui="save-slot"] figure::before { position: absolute; inset: 0; z-index: 1; background: repeating-linear-gradient(180deg, rgba(0, 0, 0, .2) 0 1px, transparent 1px 3px); content: ""; pointer-events: none; }
[data-larch-ui="save-slot"] figure span { color: var(--skin-neon); font-family: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; }
[data-larch-ui="save-slot"] figure span::before { content: "SLOT_"; }
[data-larch-ui="save-slot"] .save-slot-info small { font-family: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; }
[data-larch-ui="save-slot"] button { border-radius: 0; background: #060b16; color: var(--skin-neon); font-family: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; box-shadow: inset 0 0 0 1px var(--skin-neon); }
[data-larch-ui="save-slot"] button:hover:not(:disabled), [data-larch-ui="save-slot"] button:focus-visible { background: var(--skin-neon); color: #060b16; }
[data-larch-ui="save-slot"] button:focus-visible { outline: 2px solid var(--skin-pulse); outline-offset: 2px; }
[data-larch-ui="save-slot"] button:disabled { background: #0b1018; color: #93a3a8; box-shadow: inset 0 0 0 1px #3c4a50; }
:scope[data-larch-ui="save"] .save-slot-pagination button { border-radius: 0; background: #0d1a2b; color: #cdeff5; font-family: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--skin-neon) 35%, transparent); }
:scope[data-larch-ui="save"] .save-slot-pagination button:hover:not(:disabled), :scope[data-larch-ui="save"] .save-slot-pagination button:focus-visible { background: rgba(57, 243, 255, .18); color: #fff; }
