:scope[data-larch-ui="save"] .save-slot-pagination button.active { background: var(--skin-neon); color: #060b16; }
:scope[data-larch-ui="save"] .save-slot-pagination button:disabled { background: transparent; color: #4d6a72; box-shadow: inset 0 0 0 1px #24323a; }
/* 對話紀錄：一份往下捲的通訊紀錄。 */
