[data-larch-ui="history-entry"] b::after { color: var(--skin-pulse); content: "]"; }
@media (max-width: 640px) {
  [data-larch-ui="settings-tabs"] { padding: 0 8px; }
  [data-larch-ui="settings-tab"] { padding: 0 9px; font-size: 12px; }
  [data-larch-ui="settings-tab"] svg { display: none; }
  [data-larch-ui="settings-tab"] span::before { margin-right: 3px; }
  [data-larch-ui="settings-tab"] span::after { margin-left: 3px; }
