choices.html:
/* @larch-params {
  "neon": { "type": "color", "label": "霓虹主色", "labelEn": "Neon", "default": "#39f3ff" },
  "pulse": { "type": "color", "label": "第二色", "labelEn": "Second neon", "default": "#ff3fb4" },
  "hover": { "type": "audio", "kind": "sfx", "label": "選項滑過音效", "labelEn": "Choice hover sound", "default": "/skills/neon-signal/sfx/hover.mp3" },
  "select": { "type": "audio", "kind": "sfx", "label": "選定選項音效", "labelEn": "Choice pick sound", "default": "/skills/neon-signal/sfx/press.mp3" }
} */
:scope { gap: 10px; }
:scope.vn2-choices-floating { padding: 0; border: 0; background: none; box-shadow: none; backdrop-filter: none; }
[data-larch-ui="choice"] { min-height: 54px; padding: 10px 50px 10px 18px; gap: 14px; border: 0; border-radius: 0; background: linear-gradient(90deg, rgba(6, 11, 22, .94), rgba(6, 11, 22, .72)); color: #e6fbff; clip-path: polygon(14px 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%, 0 14px); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--skin-neon) 55%, transparent), inset 3px 0 0 var(--skin-neon); font-family: "Noto Sans TC", "PingFang TC", "Microsoft JhengHei", system-ui, sans-serif; font-size: 16px; letter-spacing: .04em; text-shadow: none; transition: background .16s, color .16s, box-shadow .16s; }
[data-larch-ui="choice-index"] { color: var(--skin-neon); font: 700 13px/1 ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; letter-spacing: .08em; }
[data-larch-ui="choice-index"]::before { color: var(--skin-pulse); content: "["; }
[data-larch-ui="choice-index"]::after { color: var(--skin-pulse); content: "]"; }
[data-larch-ui="choice-arrow"] { position: absolute; right: 18px; color: var(--skin-neon); opacity: .8; }
[data-larch-ui="choice"]:hover, [data-larch-ui="choice"]:focus-visible { background: linear-gradient(90deg, color-mix(in srgb, var(--skin-neon) 24%, #060b16), rgba(6, 11, 22, .8)); color: #fff; outline: none; box-shadow: inset 0 0 0 1px var(--skin-neon), inset 5px 0 0 var(--skin-pulse), 0 0 18px color-mix(in srgb, var(--skin-neon) 30%, transparent); }
[data-larch-ui="choice"]:hover [data-larch-ui="choice-arrow"], [data-larch-ui="choice"]:focus-visible [data-larch-ui="choice-arrow"] { color: var(--skin-pulse); opacity: 1; }
[data-larch-ui="choice"]:active { background: color-mix(in srgb, var(--skin-pulse) 26%, #060b16); }
[data-larch-ui="choice"]:disabled { background: rgba(14, 18, 26, .9); color: #93a3a8; box-shadow: inset 0 0 0 1px #3c4a50; cursor: not-allowed; }
[data-larch-ui="choice"]:disabled [data-larch-ui="choice-index"] { color: #7d8c91; }
[data-larch-ui="choice"]:disabled [data-larch-ui="choice-arrow"] { display: none; }
[data-larch-ui="choice"]:disabled::after { position: absolute; right: 16px; padding: 2px 6px; border: 1px solid #5d6b70; color: #a4b2b6; content: "LOCKED"; font: 700 10px/1.2 ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; letter-spacing: .14em; }
@media (max-width: 640px) { [data-larch-ui="choice"] { min-height: 48px; font-size: 15px; } }

gallery.html:
/* @larch-params {
  "neon": { "type": "color", "label": "霓虹主色", "labelEn": "Neon", "default": "#39f3ff" },
  "pulse": { "type": "color", "label": "第二色", "labelEn": "Second neon", "default": "#ff3fb4" },
  "open": { "type": "audio", "kind": "sfx", "label": "開啟音效", "labelEn": "Open sound", "default": "/skills/neon-signal/sfx/open.mp3" },
  "hover": { "type": "audio", "kind": "sfx", "label": "滑過音效", "labelEn": "Hover sound", "default": "/skills/neon-signal/sfx/hover.mp3" }
} */
/* CG 收藏是一面監視器牆：每張 CG 是一台 CRT 監視器，畫面上有掃描線、REC 與時間碼；還沒解鎖的只有雜訊和 NO SIGNAL。 */
:scope[data-larch-ui="gallery"] { counter-reset: ns-cam; background: radial-gradient(ellipse 70% 40% at 50% 0%, color-mix(in srgb, var(--skin-neon) 12%, transparent), transparent 70%), radial-gradient(ellipse 60% 40% at 50% 110%, color-mix(in srgb, var(--skin-pulse) 12%, transparent), transparent 70%), linear-gradient(rgba(57, 243, 255, .035) 1px, transparent 1px) 0 0 / 100% 32px, linear-gradient(90deg, rgba(57, 243, 255, .035) 1px, transparent 1px) 0 0 / 32px 100%, linear-gradient(180deg, #070b14, #03050b) !important; color: #e6fbff; font-family: "Noto Sans TC", "PingFang TC", "Microsoft JhengHei", system-ui, sans-serif; scrollbar-width: thin; scrollbar-color: color-mix(in srgb, var(--skin-neon) 50%, transparent) transparent; }
/* 上方是監控室的狀態列。 */
:scope[data-larch-ui="gallery"] > header { min-height: 0; padding: 16px max(24px, 4vw); border-bottom: 1px solid color-mix(in srgb, var(--skin-neon) 40%, transparent); background: rgba(4, 8, 16, .94); box-shadow: 0 8px 30px rgba(0, 0, 0, .5); }
:scope > header > div { text-align: center; }
:scope > header small { display: inline-flex; align-items: center; gap: 8px; color: var(--skin-pulse) !important; font: 700 11px/1.3 ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; letter-spacing: .32em; }
:scope[data-larch-ui="gallery"] > header small::before { width: 8px; height: 8px; border-radius: 50%; background: #ff4d6d; box-shadow: 0 0 8px #ff4d6d; content: ""; animation: ns-rec 1.4s steps(2, end) infinite; }
:scope > header h1 { margin: 4px 0 2px; color: #f2feff; font: 900 clamp(24px, 2.6vw, 34px)/1.15 "Noto Sans TC", "PingFang TC", "Microsoft JhengHei", system-ui, sans-serif; letter-spacing: .06em; text-shadow: 0 0 2px #fff, 0 0 14px color-mix(in srgb, var(--skin-neon) 80%, transparent), 0 0 34px color-mix(in srgb, var(--skin-neon) 45%, transparent); }
:scope > header p { margin: 0; color: var(--skin-neon); font: 600 12px/1.4 ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; letter-spacing: .08em; }
[data-larch-ui="screen-back"], [data-larch-ui="screen-close"] { display: inline-flex; align-items: center; justify-content: center; gap: 6px; min-height: 38px; padding: 0 14px 0 10px; border: 0; border-radius: 0; background: linear-gradient(135deg, transparent calc(50% - .7px), var(--skin-neon) calc(50% - .7px) calc(50% + .7px), transparent calc(50% + .7px)) 0 0 / 8px 8px no-repeat, linear-gradient(135deg, transparent calc(50% - .7px), var(--skin-neon) calc(50% - .7px) calc(50% + .7px), transparent calc(50% + .7px)) 100% 100% / 8px 8px no-repeat, rgba(6, 11, 22, .9); color: var(--skin-neon); font: 700 12px/1 ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; letter-spacing: .1em; box-shadow: inset 0 0 0 1px var(--skin-neon); clip-path: polygon(8px 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%, 0 8px); cursor: pointer; transition: background .15s, color .15s; }
