[data-larch-ui="screen-back"]:active, [data-larch-ui="screen-close"]:active { background: var(--skin-pulse); color: #060b16; }
/* 監視器：機殼、弧形的螢幕、掃描線與暗角，下巴上一顆綠燈。 */
[data-larch-ui="gallery-grid"] { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 22px; width: min(1140px, calc(100% - 64px)); padding: 30px 0 64px; }
[data-larch-ui="cg"] { counter-increment: ns-cam; position: relative; aspect-ratio: auto; overflow: visible; padding: 10px 10px 28px; border: 0; border-radius: 12px; background: radial-gradient(circle at calc(100% - 20px) calc(100% - 14px), #39ff9a 0 2.4px, rgba(57, 255, 154, .35) 3.4px, transparent 6px), repeating-linear-gradient(90deg, #2b3546 0 2px, transparent 2px 5px) 14px calc(100% - 11px) / 60px 6px no-repeat, linear-gradient(180deg, #1d2534, #10151f 70%, #0b0f17); box-shadow: inset 0 1px 0 rgba(255, 255, 255, .09), inset 0 0 0 1px #2a3445, 0 16px 34px rgba(0, 0, 0, .6); transition: box-shadow .2s; }
[data-larch-ui="cg"] > img { display: block; width: 100%; height: auto; aspect-ratio: 16 / 9; object-fit: cover; border-radius: 12px / 18px; filter: saturate(1.12) contrast(1.06); box-shadow: 0 0 0 2px #04060a; transition: filter .25s; }
