[data-larch-ui="cg"]:not(.locked):hover { box-shadow: inset 0 1px 0 rgba(255, 255, 255, .09), inset 0 0 0 1px var(--skin-neon), 0 0 26px color-mix(in srgb, var(--skin-neon) 32%, transparent), 0 16px 34px rgba(0, 0, 0, .6); }
[data-larch-ui="cg"]::after { position: absolute; inset: 10px 10px 28px; z-index: 1; border-radius: 12px / 18px; background: linear-gradient(130deg, rgba(255, 255, 255, .1), transparent 38%), repeating-linear-gradient(180deg, rgba(0, 0, 0, .3) 0 1px, transparent 1px 3px), radial-gradient(ellipse 75% 70% at 50% 50%, transparent 55%, rgba(0, 0, 0, .6)); content: ""; pointer-events: none; }
[data-larch-ui="cg"]::before { position: absolute; left: 22px; top: 18px; z-index: 2; color: #ff5470; content: "● REC"; font: 700 11px/1 ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; letter-spacing: .14em; text-shadow: 0 0 6px rgba(255, 84, 112, .9), 0 1px 2px #000; animation: ns-rec 1.4s steps(2, end) infinite; }
/* 畫面下方的 OSD：攝影機編號、名字與時間碼。 */
[data-larch-ui="cg"] figcaption { left: 10px; right: 10px; bottom: 28px; z-index: 2; gap: 8px; padding: 22px 12px 8px; border-radius: 0 0 12px 12px; background: linear-gradient(transparent, rgba(0, 0, 0, .78)); font-family: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; }
[data-larch-ui="cg"] figcaption span { flex: none; color: var(--skin-neon) !important; font: 700 11px/1 ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; letter-spacing: .08em; text-shadow: 0 0 6px color-mix(in srgb, var(--skin-neon) 70%, transparent); }
[data-larch-ui="cg"] figcaption span::before { content: "CAM "; }
[data-larch-ui="cg"] figcaption b { min-width: 0; overflow: hidden; color: #f2feff; font: 700 13px/1.3 "Noto Sans TC", "PingFang TC", "Microsoft JhengHei", system-ui, sans-serif; text-overflow: ellipsis; white-space: nowrap; text-shadow: 0 1px 2px #000; }
[data-larch-ui="cg"] figcaption::after { flex: none; margin-left: auto; color: #b8e6ee; content: "TC 0" counter(ns-cam) ":2" counter(ns-cam) ":4" counter(ns-cam); font: 600 10px/1 ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; letter-spacing: .06em; }
/* 沒有訊號：雜訊在跳、正中央一條 NO SIGNAL。 */
[data-larch-ui="cg"].locked { background: linear-gradient(180deg, #181e2a, #0d1119 70%, #0a0d14); box-shadow: inset 0 1px 0 rgba(255, 255, 255, .06), inset 0 0 0 1px #242d3b, 0 14px 30px rgba(0, 0, 0, .55); }
[data-larch-ui="cg"].locked::before { color: #93a3a8; content: "○ NO FEED"; text-shadow: none; animation: none; }
[data-larch-ui="cg"].locked > i { position: relative; display: grid; place-items: center; width: 100%; height: auto; aspect-ratio: 16 / 9; overflow: hidden; border-radius: 12px / 18px; background: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='180' height='180'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='2' stitchTiles='stitch'/><feColorMatrix type='saturate' values='0'/></filter><rect width='100%' height='100%' filter='url(%23n)' opacity='.9'/></svg>") 0 0 / 180px 180px, linear-gradient(180deg, #3a4150, #1b2029); color: #e6fbff; box-shadow: 0 0 0 2px #04060a; animation: ns-static .5s steps(4, end) infinite; }
[data-larch-ui="cg"].locked > i::after { position: relative; z-index: 1; padding: 6px 16px; background: #04060a; color: #f2feff; content: "NO SIGNAL"; font: 800 14px/1 ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; letter-spacing: .3em; box-shadow: 0 0 0 1px rgba(242, 254, 255, .5); }
[data-larch-ui="cg"].locked > i svg { position: absolute; right: 12px; top: 12px; z-index: 1; width: 16px; height: 16px; color: #f2feff; filter: drop-shadow(0 1px 2px #000); }
[data-larch-ui="cg"].locked figcaption span { color: #b8c9cd !important; text-shadow: none; }
[data-larch-ui="cg"].locked figcaption b { color: #cfdade; }
[data-larch-ui="cg"].locked figcaption::after { color: #93a3a8; content: "--:--:--"; }
[data-larch-ui="cg"] .cg-download { top: 16px; right: 16px; z-index: 3; width: 32px; height: 32px; border: 0; border-radius: 0; background: rgba(6, 11, 22, .9); color: var(--skin-neon); box-shadow: inset 0 0 0 1px var(--skin-neon); backdrop-filter: none; }
