[data-larch-ui="cg"] .cg-download:focus-visible { outline: 2px solid var(--skin-pulse); outline-offset: 2px; }
@keyframes ns-rec { 50% { opacity: .25; } }
@keyframes ns-static { 0% { background-position: 0 0, 0 0; } 25% { background-position: -60px 40px, 0 0; } 50% { background-position: 30px -70px, 0 0; } 75% { background-position: -90px -20px, 0 0; } 100% { background-position: 0 0, 0 0; } }

/* 選擇章節：一排資料卡匣，插槽上方是終端機的標題列。 */
:scope[data-larch-ui="chapters"] { position: absolute; inset: 0; display: flex; flex-direction: column; width: auto; height: auto; max-height: none; margin: 0; padding: 22px max(24px, calc(50% - 560px)) 44px; overflow: auto; border: 0; border-radius: 0; background: radial-gradient(ellipse 60% 40% at 50% 0%, color-mix(in srgb, var(--skin-neon) 12%, transparent), transparent 70%), repeating-linear-gradient(180deg, rgba(255, 255, 255, .022) 0 1px, transparent 1px 3px), linear-gradient(rgba(57, 243, 255, .035) 1px, transparent 1px) 0 0 / 100% 32px, linear-gradient(90deg, rgba(57, 243, 255, .035) 1px, transparent 1px) 0 0 / 32px 100%, linear-gradient(180deg, #070b14, #03050b); color: #e6fbff; box-shadow: none; font-family: "Noto Sans TC", "PingFang TC", "Microsoft JhengHei", system-ui, sans-serif; scrollbar-width: thin; scrollbar-color: color-mix(in srgb, var(--skin-neon) 50%, transparent) transparent; }
