:scope[data-larch-ui="chapters"] > header > button:first-child { justify-self: start; }
:scope[data-larch-ui="chapters"] > header > button:last-child { justify-self: end; }
:scope[data-larch-ui="chapters"] > header small::before { color: var(--skin-neon); content: "> "; }
:scope[data-larch-ui="chapters"] > header h1::after { margin-left: 6px; color: var(--skin-neon); content: "_"; font-family: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; animation: ns-rec 1.1s steps(2, end) infinite; }
[data-larch-ui="chapter-grid"] { position: relative; display: flex; flex-wrap: wrap; justify-content: center; align-self: center; gap: 28px 30px; width: fit-content; max-width: 100%; margin: auto 0; padding: 44px 34px 30px; background: linear-gradient(180deg, #04070d, #0a1019); box-shadow: inset 0 3px 14px rgba(0, 0, 0, .85), inset 0 0 0 1px rgba(57, 243, 255, .2); }
[data-larch-ui="chapter-grid"]::before { position: absolute; left: 16px; top: 14px; color: var(--skin-pulse); content: "SLOT BAY // INSERT CARTRIDGE"; font: 700 10px/1 ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; letter-spacing: .26em; }
/* 卡匣：上緣有防滑紋，右上角斜切，正面貼著畫面標籤，底下一排金屬接點。 */
[data-larch-ui="chapter"] { position: relative; display: grid; align-content: start; gap: 6px; width: 248px; min-width: 0; padding: 22px 14px 30px; border: 0; border-radius: 0; background: linear-gradient(45deg, transparent calc(50% - .8px), color-mix(in srgb, var(--skin-neon) 60%, transparent) calc(50% - .8px) calc(50% + .8px), transparent calc(50% + .8px)) 100% 0 / 30px 30px no-repeat, repeating-linear-gradient(90deg, rgba(255, 255, 255, .07) 0 3px, transparent 3px 7px) 14px 7px / calc(100% - 64px) 8px no-repeat, linear-gradient(180deg, #1c2533, #121924 60%, #0e141d); color: #e6fbff; text-align: left; clip-path: polygon(0 0, calc(100% - 30px) 0, 100% 30px, 100% 100%, 0 100%); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--skin-neon) 35%, transparent), inset 3px 0 0 color-mix(in srgb, var(--skin-neon) 60%, transparent); cursor: pointer; transition: box-shadow .2s, background .2s; }
[data-larch-ui="chapter"]::after { position: absolute; left: 18px; right: 18px; bottom: 8px; height: 12px; background: repeating-linear-gradient(90deg, #c9a45a 0 6px, transparent 6px 10px); content: ""; opacity: .85; }
[data-larch-ui="chapter"] > span { position: relative; width: 100%; aspect-ratio: 16 / 10; display: grid; place-items: center; overflow: hidden; border-radius: 0; background: repeating-linear-gradient(135deg, #16202d 0 8px, #121a25 8px 16px); color: var(--skin-neon); box-shadow: 0 0 0 1px #04060a, 0 0 0 3px #2a3445; }
[data-larch-ui="chapter"] > span img { width: 100%; height: 100%; object-fit: cover; filter: saturate(1.1) contrast(1.05); }
[data-larch-ui="chapter"] > span::after { position: absolute; inset: 0; background: repeating-linear-gradient(180deg, rgba(0, 0, 0, .25) 0 1px, transparent 1px 3px), linear-gradient(180deg, transparent 55%, rgba(4, 6, 10, .7)); content: ""; pointer-events: none; }
[data-larch-ui="chapter"] > span > svg { width: 34px; height: 34px; filter: drop-shadow(0 0 8px var(--skin-neon)); }
[data-larch-ui="chapter"] > span > i { left: 0; top: auto; bottom: 0; z-index: 1; padding: 4px 8px; border-radius: 0; background: var(--skin-neon); color: #060b16; font: 800 11px/1 ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; letter-spacing: .1em; }
[data-larch-ui="chapter"] > span > i::before { content: "FILE_"; }
[data-larch-ui="chapter"] > b { margin-top: 6px; overflow: hidden; color: #f2feff; font: 800 16px/1.35 "Noto Sans TC", "PingFang TC", "Microsoft JhengHei", system-ui, sans-serif; text-overflow: ellipsis; white-space: nowrap; }
[data-larch-ui="chapter"] > small { overflow: hidden; color: #a9d6de; font: 12px/1.5 ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; text-overflow: ellipsis; white-space: nowrap; }
[data-larch-ui="chapter"] > small::before { color: var(--skin-pulse); content: "// "; }
[data-larch-ui="chapter"]:hover { border: 0; background: linear-gradient(45deg, transparent calc(50% - .8px), color-mix(in srgb, var(--skin-neon) 100%, transparent) calc(50% - .8px) calc(50% + .8px), transparent calc(50% + .8px)) 100% 0 / 30px 30px no-repeat, repeating-linear-gradient(90deg, rgba(255, 255, 255, .1) 0 3px, transparent 3px 7px) 14px 7px / calc(100% - 64px) 8px no-repeat, linear-gradient(180deg, #223047, #142031 60%, #0f1724); box-shadow: inset 0 0 0 1px var(--skin-neon), inset 3px 0 0 var(--skin-pulse), 0 0 24px color-mix(in srgb, var(--skin-neon) 30%, transparent); }
[data-larch-ui="chapter"]:hover > span img { filter: saturate(1.2) contrast(1.1) brightness(1.08); }
[data-larch-ui="chapter"]:focus-visible { outline: 2px solid var(--skin-pulse); outline-offset: -6px; box-shadow: inset 0 0 0 1px var(--skin-neon), inset 3px 0 0 var(--skin-pulse); }
[data-larch-ui="chapter"]:active { background: linear-gradient(180deg, #2a1830, #160f20); }
[data-larch-ui="chapter"]:disabled { cursor: not-allowed; filter: grayscale(.8); }
@media (max-width: 760px) {
  :scope[data-larch-ui="gallery"] > header { padding: 12px 14px; gap: 10px; }
  [data-larch-ui="screen-back"] { width: 38px; padding: 0; font-size: 0; gap: 0; }
  [data-larch-ui="gallery-grid"] { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; width: calc(100% - 24px); padding: 18px 0 40px; }
  [data-larch-ui="cg"] { padding: 6px 6px 18px; border-radius: 9px; }
  [data-larch-ui="cg"]::after, [data-larch-ui="cg"] > img, [data-larch-ui="cg"].locked > i { border-radius: 8px / 12px; }
  [data-larch-ui="cg"]::after { inset: 6px 6px 18px; }
  [data-larch-ui="cg"]::before { left: 13px; top: 12px; font-size: 9px; }
  [data-larch-ui="cg"] figcaption { left: 6px; right: 6px; bottom: 18px; gap: 5px; padding: 14px 7px 5px; }
  [data-larch-ui="cg"] figcaption span::before { content: "C"; }
  [data-larch-ui="cg"] figcaption b { font-size: 11px; }
  [data-larch-ui="cg"] figcaption::after { display: none; }
  [data-larch-ui="cg"].locked > i::after { padding: 4px 8px; font-size: 10px; letter-spacing: .16em; }
  :scope[data-larch-ui="chapters"] { padding: 14px 14px 32px; }
  :scope[data-larch-ui="chapters"] > header { grid-template-columns: auto minmax(0, 1fr) auto; gap: 10px; margin-bottom: 20px; }
  :scope[data-larch-ui="chapters"] > header > button:first-child { grid-column: auto; width: 40px; padding: 0; font-size: 0; gap: 0; }
  [data-larch-ui="chapter-grid"] { gap: 14px; width: 100%; padding: 36px 12px 16px; }
  [data-larch-ui="chapter-grid"]::before { left: 12px; letter-spacing: .14em; }
