  [data-larch-ui="chapter"] > b { font-size: 14px; }
  [data-larch-ui="chapter"] > small { font-size: 11px; }
}
@media (prefers-reduced-motion: reduce) { :scope > header small::before, [data-larch-ui="cg"]::before, [data-larch-ui="cg"].locked > i, :scope[data-larch-ui="chapters"] > header h1::after { animation: none; } [data-larch-ui="cg"], [data-larch-ui="cg"] > img, [data-larch-ui="chapter"] { transition: none; } }

