/* @larch-params {
  "neon": { "type": "color", "label": "霓虹主色", "labelEn": "Neon", "default": "#39f3ff" },
  "pulse": { "type": "color", "label": "第二色", "labelEn": "Second neon", "default": "#ff3fb4" },
  "open": { "type": "audio", "kind": "sfx", "label": "打開背包音效", "labelEn": "Bag open sound", "default": "/skills/neon-signal/sfx/open.mp3" },
  "close": { "type": "audio", "kind": "sfx", "label": "關上背包音效", "labelEn": "Bag close sound", "default": "/skills/neon-signal/sfx/close.mp3" },
  "select": { "type": "audio", "kind": "sfx", "label": "選道具音效", "labelEn": "Item pick sound", "default": "/skills/neon-signal/sfx/press.mp3" },
  "use": { "type": "audio", "kind": "sfx", "label": "使用道具音效", "labelEn": "Item use sound", "default": "/skills/neon-signal/sfx/use.mp3" },
  "hover": { "type": "audio", "kind": "sfx", "label": "道具滑過音效", "labelEn": "Item hover sound", "default": "/skills/neon-signal/sfx/hover.mp3" }
} */
/* 側邊資料面板：背包從右邊滑出一整條，上面是掃描中的道具資料，下面是編號清單。 */
:scope[data-larch-ui="bag-button"], :scope[data-larch-ui="bag"], :scope[data-larch-ui="item-tip"] { --inventory-accent: var(--skin-neon) !important; --inventory-surface: #060b16 !important; --inventory-item: #0d1a2b !important; --inventory-text: #e6fbff !important; --inventory-radius: 0px !important; --inventory-surface-opacity: 100% !important; }
:scope[data-larch-ui="bag-button"] { border: 0; border-radius: 0; background: rgba(6, 11, 22, .9); color: var(--skin-neon); clip-path: polygon(10px 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%, 0 10px); box-shadow: inset 0 0 0 1px var(--skin-neon), 0 0 14px color-mix(in srgb, var(--skin-neon) 35%, transparent); font-family: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; }
:scope[data-larch-ui="bag-button"]:hover, :scope[data-larch-ui="bag-button"]:focus-visible { background: var(--skin-neon); color: #060b16; outline: none; }
[data-larch-ui="bag-button-count"] { position: static; border-radius: 0; background: var(--skin-pulse); color: #060b16; box-shadow: none; }
:scope[data-larch-ui="bag-scrim"] { background: linear-gradient(90deg, rgba(2, 4, 10, .2), rgba(2, 4, 10, .75)); backdrop-filter: blur(2px); }
/* 整條貼在右邊，從右邊滑進來。 */
:scope[data-larch-ui="bag"] { left: auto; right: 0; top: 0; bottom: 0; width: min(440px, 100%); height: 100%; max-height: none; translate: none; transform: none !important; display: flex; flex-direction: column; border: 0; border-left: 2px solid var(--skin-neon); border-radius: 0; background: repeating-linear-gradient(180deg, rgba(255, 255, 255, .025) 0 1px, transparent 1px 3px), linear-gradient(180deg, rgba(8, 16, 30, .97), rgba(3, 6, 13, .98)); color: #e6fbff; box-shadow: -10px 0 40px color-mix(in srgb, var(--skin-neon) 22%, transparent); font-family: "Noto Sans TC", "PingFang TC", "Microsoft JhengHei", system-ui, sans-serif; animation: slide-in .38s cubic-bezier(.2, .9, .25, 1) both; }
@keyframes slide-in { from { translate: 100% 0; } to { translate: 0 0; } }
[data-larch-ui="bag-header"] { min-height: 0; padding: 22px 22px 14px; border-bottom: 1px solid color-mix(in srgb, var(--skin-neon) 35%, transparent); }
[data-larch-ui="bag-title"] small { color: var(--skin-pulse); font: 700 11px/1 ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; letter-spacing: .34em; }
[data-larch-ui="bag-title"] small::after { color: var(--skin-neon); content: " ▮"; animation: blink 1s steps(2, end) infinite; }
[data-larch-ui="bag-title"] h2 { margin: 6px 0 2px; color: #f2feff; font-size: 22px; letter-spacing: .08em; text-shadow: 0 0 12px color-mix(in srgb, var(--skin-neon) 60%, transparent); }
[data-larch-ui="bag-title"] p { color: var(--skin-neon); font: 500 12px/1.4 ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; }
[data-larch-ui="wallet"] { border: 1px solid color-mix(in srgb, var(--skin-neon) 60%, transparent); border-radius: 0; background: transparent; color: #e6fbff; }
[data-larch-ui="wallet"] > span { border-radius: 0; background: none; }
[data-larch-ui="wallet"] b { color: var(--skin-neon); font-family: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; }
[data-larch-ui="wallet"] small { color: #e6fbff; }
[data-larch-ui="bag-close"] { border: 1px solid var(--skin-neon); border-radius: 0; background: transparent; color: var(--skin-neon); }
[data-larch-ui="bag-close"]:hover, [data-larch-ui="bag-close"]:focus-visible { background: var(--skin-neon); color: #060b16; outline: none; }
/* 上：掃描卡；下：清單。 */
[data-larch-ui="bag-body"] { flex: 1; display: flex; flex-direction: column-reverse; min-height: 0; }
[data-larch-ui="item-detail"], [data-larch-ui="bag-empty"] { flex: none; position: relative; margin: 16px 18px 6px; padding: 16px 18px; border: 0; background: linear-gradient(135deg, color-mix(in srgb, var(--skin-neon) 12%, transparent), transparent 60%), rgba(13, 26, 43, .85); color: #e6fbff; clip-path: polygon(16px 0, 100% 0, 100% calc(100% - 16px), calc(100% - 16px) 100%, 0 100%, 0 16px); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--skin-neon) 55%, transparent); overflow: hidden; }
[data-larch-ui="item-detail"]::after { position: absolute; left: 0; right: 0; height: 30%; background: linear-gradient(180deg, transparent, color-mix(in srgb, var(--skin-neon) 16%, transparent), transparent); content: ""; pointer-events: none; animation: scan 2.6s linear infinite; }
@keyframes scan { from { top: -30%; } to { top: 100%; } }
[data-larch-ui="detail-icon"] { width: 56px; height: 56px; border-radius: 0; background: rgba(6, 11, 22, .9); color: var(--skin-neon); clip-path: polygon(25% 0, 75% 0, 100% 50%, 75% 100%, 25% 100%, 0 50%); box-shadow: inset 0 0 0 1px var(--skin-neon); }
[data-larch-ui="detail-name"] { color: #f2feff; font-size: 18px; }
[data-larch-ui="detail-count"] { color: var(--skin-pulse); font-family: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; letter-spacing: .1em; }
[data-larch-ui="detail-desc"] { color: #c5eef5; font-size: 14px; line-height: 1.7; }
[data-larch-ui="detail-effects"] { border-top: 1px dashed color-mix(in srgb, var(--skin-neon) 40%, transparent); }
[data-larch-ui="detail-effects"] li { color: #c5eef5; font-family: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; }
[data-larch-ui="item-use"] { width: 100%; border: 0; border-radius: 0; background: transparent; color: var(--skin-neon); box-shadow: inset 0 0 0 1px var(--skin-neon); font: 700 13px/1 ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; letter-spacing: .3em; }
[data-larch-ui="item-use"]::before { content: "> "; }
[data-larch-ui="item-use"]:hover, [data-larch-ui="item-use"]:focus-visible { background: var(--skin-neon); color: #060b16; outline: none; filter: none; }
[data-larch-ui="bag-empty"] { display: grid; justify-items: start; gap: 6px; }
[data-larch-ui="bag-empty"] b { color: #f2feff; }
[data-larch-ui="bag-list"] { flex: 1; min-height: 0; }
[data-larch-ui="bag-search"] { margin: 10px 18px 0; border: 1px solid color-mix(in srgb, var(--skin-neon) 50%, transparent); border-radius: 0; background: rgba(6, 11, 22, .9); color: #e6fbff; }
/* 清單：每列前面有編號 01、02…，選中的那列左邊亮一條。 */
[data-larch-ui="bag-grid"] { counter-reset: neon-item; grid-template-columns: 1fr; gap: 4px; padding: 10px 18px 22px; }
[data-larch-ui="slot-empty"] { display: none; }
[data-larch-ui="item"] { counter-increment: neon-item; min-height: 48px; display: grid; grid-template-columns: 30px 30px minmax(0, 1fr) auto; place-items: center start; gap: 10px; padding: 6px 14px 6px 12px; border: 0; border-radius: 0; background: rgba(13, 26, 43, .7); color: #e6fbff; box-shadow: inset 2px 0 0 color-mix(in srgb, var(--skin-neon) 35%, transparent); }
[data-larch-ui="item"]::before { grid-column: 1; color: var(--skin-pulse); content: counter(neon-item, decimal-leading-zero); font: 700 12px/1 ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; }
[data-larch-ui="item"] [data-larch-ui="item-icon"] { grid-column: 2; width: 30px; height: 30px; border-radius: 0; background: none; color: var(--skin-neon); }
[data-larch-ui="item"] [data-larch-ui="item-icon"] :is(img, svg) { width: 26px; height: 26px; }
[data-larch-ui="item-name"] { grid-column: 3; width: 100%; font-size: 15px; text-align: left; }
[data-larch-ui="item-count"] { position: static; grid-column: 4; padding: 0; border-radius: 0; background: none; color: var(--skin-neon); font: 700 13px/1 ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace; }
[data-larch-ui="item-keep"] { position: static; grid-column: 4; color: var(--skin-pulse); }
[data-larch-ui="item"]:hover, [data-larch-ui="item"]:focus-visible { background: color-mix(in srgb, var(--skin-neon) 14%, #0d1a2b); color: #fff; outline: none; box-shadow: inset 3px 0 0 var(--skin-neon); }
[data-larch-ui="item"]:focus-visible { box-shadow: inset 3px 0 0 var(--skin-neon), inset 0 0 0 1px var(--skin-neon); }
[data-larch-ui="item"][aria-selected="true"] { background: linear-gradient(90deg, color-mix(in srgb, var(--skin-neon) 26%, #0d1a2b), rgba(13, 26, 43, .7)); color: #fff; box-shadow: inset 4px 0 0 var(--skin-pulse), 0 0 14px color-mix(in srgb, var(--skin-neon) 25%, transparent); }
:scope[data-larch-ui="item-tip"] { border: 0; border-radius: 0; background: rgba(6, 11, 22, .97); color: #e6fbff; box-shadow: inset 0 0 0 1px var(--skin-neon); font-family: "Noto Sans TC", "PingFang TC", "Microsoft JhengHei", system-ui, sans-serif; }
:scope[data-larch-ui="item-tip"] small { color: #c5eef5; }
@keyframes blink { 50% { opacity: 0; } }
@media (prefers-reduced-motion: reduce) { :scope[data-larch-ui="bag"], [data-larch-ui="item-detail"]::after, [data-larch-ui="bag-title"] small::after { animation: none; } }
